    assert client.get(f"/api/v1/vsb/{vid}/website/page/evil").status_code == 404
    assert client.get(f"/api/v1/vsb/{vid}/website").json()["page_count"] == 3
    assert client.post("/api/v1/vsb/nope-xyz-404/website").status_code == 404


