def test_w442_economy_cluster_integrity_holds(client, monkeypatch):
    # W442 — the economy cluster's money-integrity fixes stay fixed.
    import uuid as _uuid
    uid = f"w442-{_uuid.uuid4().hex[:8]}"

    # 1. NaN/inf are refused AT THE MODEL (they used to pass every engine guard: nan <= 0 is
    #    False, and one NaN posting permanently disabled the insufficient-funds check). The
    #    TestClient's serializer refuses inf, so the bodies go raw — exactly how an attacker
    #    would send them (Python's server-side json parser accepts Infinity/NaN by default).
    _hdr = {"Content-Type": "application/json"}
    for path, raw in [
        ("/api/v1/economy/transfer", '{"from_vsb": "%s", "to_vsb": "x", "amount": Infinity}' % uid),
        ("/api/v1/economy/ventures/return", '{"vsb_id": "%s", "holding_id": "h", "amount": NaN}' % uid),
        ("/api/v1/economy/cycle", '{"vsb_id": "%s", "revenue": NaN}' % uid),
        ("/api/v1/economy/owner-payments/payout", '{"vsb_id": "%s", "amount": Infinity}' % uid),
    ]:
        assert client.post(path, content=raw, headers=_hdr).status_code == 422, path
    # belt-and-braces: the engine's own validator refuses non-finite amounts too
    import math
    import pytest as _pytest
    from agentic_core.economy.transfers import validate_transfer
    with _pytest.raises(ValueError, match="finite"):
        validate_transfer(uid, "someone-else", float("nan"))

    # 2. a caller-asserted venture "return" is bounded by invested capital (inf/10^12 on a tiny
    #    holding used to mint WST from nothing into the next cycle's waterfall)
    from agentic_core.economy.ventures import record_positions, record_return
    record_positions(uid, {"positions": [{"id": "h1", "name": "T", "domain": "care",
                                          "score": 0.5, "amount_wst": 50.0}]})
    r = client.post("/api/v1/economy/ventures/return",
                    json={"vsb_id": uid, "holding_id": "h1", "amount": 100000})
    assert r.status_code == 400 and "money" in r.json()["detail"].lower()
    ok = client.post("/api/v1/economy/ventures/return",
                     json={"vsb_id": uid, "holding_id": "h1", "amount": 200}).json()
    assert "caller_asserted" in ok["amount_source"] and ok["ueg_logged"] in (True, False)

    # 3. the §3 materiality gate now SEES the recycle queues (stuffing them used to bypass
    #    Change Control: gate saw revenue=0 while run_cycle consumed the queued heap ungated)
    from agentic_core.economy import governance as gv
    monkeypatch.setattr(gv, "MATERIALITY_WST", 100.0)
    res = client.post("/api/v1/economy/cycle", json={"vsb_id": uid, "revenue": 0}).json()
    assert res["cycle"] is None, "queued 200 WST distributed ungated despite materiality 100"
    assert res["governance"]["status"] == "held_for_change_control"

    # 4. hold identity carries the ACTION KIND — a cycle approval can no longer release a transfer
    from agentic_core.api import change_control as cca
    h_t, _ = gv._materiality_gate(uid, 500.0, source="transfer", counterparty="someone-else")
    h_c, _ = gv._materiality_gate(uid, 500.0, source="api")
    t_title = (cca._load_change(h_t["cca_id"]) or {}).get("title", "")
    c_title = (cca._load_change(h_c["cca_id"]) or {}).get("title", "")
    assert "material transfer" in t_title and "material distribution" in c_title

    # 5. a BLOCKED constitutional verdict means NOTHING ran (it used to fall into the
    #    missing-output fallback and run the cycle anyway — "blocked" beside moved money)
    import asyncio
    import agentic_core.gaas.v5 as _g5

    class _BlockedRes:
        status, output, checkpoint_id = "blocked", None, "chk-w442"

    class _FakeGov:
        def __init__(self, *a, **k): pass
        async def intercept(self, ctx, action): return _BlockedRes()

    monkeypatch.setattr(_g5, "UnifiedConstitutionalInterceptorV16Omega", _FakeGov)
    out = asyncio.run(gv.governed_cycle(f"{uid}-b", "waqf_ltd_hybrid", "Rehan", 100.0))
    assert out["cycle"] is None and out["governance"]["status"] == "blocked"

    # 6. /status resolves attribution from the stores instead of echoing the caller's claim
    st = client.get(f"/api/v1/economy/status?vsb_id={uid}&entity_type=charity").json()
    assert st["attribution"]["entity_type_source"] in ("caller_claimed", "living_registry", "vsb_store")
    # 7. /close-period reports whether the tamper-evident event actually landed + its basis
    cl = client.post("/api/v1/economy/close-period", json={"vsb_id": uid}).json()
    assert isinstance(cl["ueg_logged"], bool) and cl["entity_type_source"]

    # 8. charity signals: junk values are rejected AND REPORTED, never a 500; ingested rows are
    #    labelled caller-asserted, and the candidates disclaimer is COMPUTED from the pool
    monkeypatch.setenv("CHARITY_LIVE_SIGNALS_ENABLED", "true")
    sig = client.post("/api/v1/economy/charity/signals", json={"signals": [
        {"id": f"sig-{uid}", "cause": "Test relief", "urgency": 0.9, "gravity": 0.8,
         "reach": 0.7, "trust": 0.9, "donation_100pct": True},
        {"id": "junk", "cause": "Bad row", "urgency": "high"},
    ]})
    assert sig.status_code == 200
    body = sig.json()
    assert body["ingested"] == 1 and body["rejected"] and body["rejected"][0]["id"] == "junk"
    cand = client.get("/api/v1/economy/charity/candidates?top=20").json()
    mine = next(c for c in cand["candidates"] if c["id"] == f"sig-{uid}")
    assert "caller-asserted" in mine["weights_source"]
    assert mine["donation_100pct_verified"] == "not_checked"
    assert cand["pool"]["ingested_signals"] >= 1 and "signal" in cand["disclaimer"].lower()

    # 9. the money store survives concurrent writers (it had NO lock: last-writer-wins lost
    #    postings — the documented shared-store concurrency class, on the LEDGER itself)
    import threading
    from agentic_core.economy.ledger import VirtualLedger
    def _post():
        VirtualLedger(f"{uid}-conc").record("revenue", 10.0, memo="conc")
    threads = [threading.Thread(target=_post) for _ in range(8)]
    for t in threads: t.start()
    for t in threads: t.join()
    led = VirtualLedger(f"{uid}-conc")
    assert len(led._data["entries"]) == 8, f"lost {8 - len(led._data['entries'])} of 8 concurrent postings"
    assert led.trial_balance()["balanced"]

    # ── refuter-round catches stay fixed ──────────────────────────────────────
    # 10. the 10× bound is CUMULATIVE (per-call caps were defeated by repetition: N calls of
    #     ≤10× each minted without limit). invested 50 → cap 500; 200 already returned above.
    ok2 = client.post("/api/v1/economy/ventures/return",
                      json={"vsb_id": uid, "holding_id": "h1", "amount": 200})
    assert ok2.status_code == 200          # cumulative 400 ≤ 500
    over = client.post("/api/v1/economy/ventures/return",
                       json={"vsb_id": uid, "holding_id": "h1", "amount": 200})
    assert over.status_code == 400 and "cumulative" in over.json()["detail"].lower()
    # 11. the portfolio RESPONSE carries the pending/returns figures (they lived only in the
    #     store, so the panel's headline badge read 0 forever — the invisibility re-created)
    pf = client.get(f"/api/v1/economy/ventures/portfolio?vsb_id={uid}").json()
    assert pf["pending_returns_wst"] >= 200 and pf["returns_total"] >= 400
    # 12. board-pack resolves attribution instead of echoing the caller's claim
    bp = client.get(f"/api/v1/economy/board-pack?vsb_id={uid}&entity_type=charity").json()
    assert bp["attribution"]["entity_type_source"] in ("caller_claimed", "living_registry", "vsb_store")
    # 13. candidates expose the UNFILTERED id universe (validating typed exclusions against the
    #     exclusion-filtered pool false-alarmed on every correct exclusion)
    assert f"sig-{uid}" in client.get("/api/v1/economy/charity/candidates").json()["all_cause_ids"]

    # cleanup (refuter catch: the ingested signal row otherwise accumulates in the persistent
    # shared test store on every run until it pushes itself out of top-20 and self-fails)
    from agentic_core.config import atomic_write_json as _awj
    from agentic_core.economy.charity import _SIGNALS_STORE, approved_signals as _sigs
    _awj(_SIGNALS_STORE, [s for s in _sigs() if s["id"] != f"sig-{uid}"])


def test_w443_agent_hub_hardened_and_honest(client):
    # W443 — the hub cluster: identity/filename validation, the mandated store pattern,
    # honest bus semantics (delivery counts, records-not-executions), and organism provenance.
    import uuid as _uuid
    aid = f"w443-{_uuid.uuid4().hex[:8]}"

    # 1. filename-unsafe ids are refused at the boundary (they used to become disk paths:
    #    a crafted agent_id could write or delete .json files outside the hub's stores)
    for path, body in [
        ("/api/v1/hub/agents/register", {"agent_id": "..\\..\\evil", "role": "ENGINEERING"}),
        ("/api/v1/hub/message", {"sender_id": "../x", "sender_role": "USER", "content": "hi"}),
        ("/api/v1/hub/claude-code-handoff", {"from_agent": "a/b", "task_title": "t", "task_description": "d"}),
    ]:
        assert client.post(path, json=body).status_code == 422, path

    # 2. re-registration is genuinely idempotent (the bespoke writer 500'd on Windows while
    #    the docstring claimed idempotence), and registered_at survives the refresh
    r1 = client.post("/api/v1/hub/agents/register", json={"agent_id": aid, "role": "ENGINEERING"})
    r2 = client.post("/api/v1/hub/agents/register", json={"agent_id": aid, "role": "ENGINEERING"})
    assert r1.status_code == 201 and r2.status_code == 201
    assert r1.json()["registered_at"] == r2.json()["registered_at"]

    # 3. honest bus semantics: the response says how many live subscribers actually received
    #    the message (none here), and the dead read_by field is gone
    m = client.post("/api/v1/hub/message",
                    json={"sender_id": aid, "sender_role": "USER", "content": "salaam"})
    assert m.status_code == 201
    assert m.json()["delivered_to_live_subscribers"] == 0
    assert "read_by" not in m.json()
    # oversized content is refused, not stored
    assert client.post("/api/v1/hub/message",
                       json={"sender_id": aid, "sender_role": "USER",
                             "content": "x" * 16001}).status_code == 422

    # 4. last_active is a real measurement again (the old writer silently failed on every
    #    touch, freezing it at registration forever)
    ag = client.get("/api/v1/hub/agents").json()
    rec = next(a for a in ag["registered"] if a["agent_id"] == aid)
    assert rec["last_active"] != rec["registered_at"]
    # and the participants view splits honest registrations from the live swarm roster
    assert len(ag["platform_roster"]) >= 5 and "presence record" in ag["note"]

    # 5. a handoff is a RECORD, visible and status-tracked — never a narrated execution
    h = client.post("/api/v1/hub/claude-code-handoff",
                    json={"from_agent": aid, "task_title": "T", "task_description": "D"}).json()
    assert h["status"] == "recorded" and "no executor is subscribed" in h["note"].lower()
    hid = h["handoff_id"]
    ls = client.get("/api/v1/hub/handoffs").json()
    mine = next(x for x in ls["handoffs"] if x["handoff_id"] == hid)
    assert mine["status"] == "recorded" and mine["status_history"]
    up = client.post(f"/api/v1/hub/handoffs/{hid}/status", json={"status": "done"})
    assert up.status_code == 200 and up.json()["status"] == "done"
    assert client.post(f"/api/v1/hub/handoffs/{_uuid.uuid4().hex}/status",
                       json={"status": "done"}).status_code == 404

    # 6. organism provenance: with zero live subscribers, posting fires NO nervous signal
    #    (letters in a dead letterbox are not "organism thinking"), and any hub signal that
    #    does fire carries the hub: source prefix — never an organic-looking one
    sig = client.get("/api/v1/organism/nervous/signals?n=100")
    if sig.status_code == 200:
        srcs = [str(s.get("source", "")) for s in (sig.json().get("signals") or [])]
        assert not any(s.startswith("hub.") for s in srcs), "old organic-masquerade source is back"
        assert not any(s.startswith("hub:") for s in srcs), "hub signal fired with no live subscriber"

    # cleanup (refuter catch: this test otherwise leaks 6 files per run into the persistent
    # shared test store — the W394 accumulation class; the sweep never fires under pytest)
    from agentic_core.api.agent_hub import _HANDOFF_DIR, _MSG_DIR, _REG_DIR
    for d in (_MSG_DIR, _HANDOFF_DIR):
        for f in d.glob("*.json"):
            try:
                if aid in f.name or aid in f.read_text(encoding="utf-8"):
                    f.unlink()
            except OSError:
                pass
    (_REG_DIR / f"{aid}.json").unlink(missing_ok=True)


def test_w444_residual_clusters_hardened_and_honest(client):
    # W444 — the three residual clusters (qep 7, marketplace 5, organism 5): the fixes hold.
    import uuid as _uuid
    uid = f"w444-{_uuid.uuid4().hex[:8]}"

    # 1. the PARALLEL marketplace is retired: its ungoverned create path is gone, while the
    #    real (screened, owner-stamped) marketplace still serves the shared URL namespace
    r = client.post("/api/v1/marketplace/list", json={"title": "x", "description": "y"})
    assert r.status_code in (404, 405), f"the ungoverned parallel create path is back: {r.status_code}"
    assert client.get("/api/v1/marketplace/listings").status_code == 200

    # 2. the AI valuation refuses on the floor rather than shipping a template as a valuation
    v = client.post("/api/v1/marketplace/value", json={"title": "T", "description": "D"})
    assert v.status_code == 503 and "fabrication" in v.json()["detail"].lower()
    # and the fund report labels floor-served output instead of presenting it as CIO analysis
    fr = client.post("/api/v1/fund/report", json={})
    if fr.status_code == 200:
        body = fr.json()
        assert "served_by" in body
        if body["served_by"] == "native":
            assert "floor_note" in body

    # 3. PATCH validates the merged listing (a junk price used to persist verbatim, then the
    #    next load silently DROPPED the record — self-corruption into invisibility)
    made = client.post("/api/v1/marketplace/listings",
                       json={"name": f"L-{uid}", "description": "test listing",
                             "creator_id": "community"}).json()
    lid = made["id"]
    assert client.patch(f"/api/v1/marketplace/listings/{lid}",
                        json={"price_wst": "free"}).status_code == 422
    assert client.patch(f"/api/v1/marketplace/listings/{lid}",
                        json={"price_wst": -5}).status_code == 422
    ok = client.patch(f"/api/v1/marketplace/listings/{lid}", json={"price_wst": 25})
    assert ok.status_code == 200 and ok.json()["price_wst"] == 25
    # 4. purchase quantity is bounded
    assert client.post(f"/api/v1/marketplace/listings/{lid}/purchase",
                       json={"quantity": 0}).status_code == 422
    # 5. a SOLD listing survives deletion as a draft (receipts must keep resolving);
    #    an unsold one deletes cleanly
    from agentic_core.api.marketplace import _load as _ml, _save as _ms
    _l = _ml(lid); _l.sales_count = 1; _ms(_l)
    d1 = client.delete(f"/api/v1/marketplace/listings/{lid}").json()
    assert d1["retired_to_draft"] == lid and d1["deleted"] is None
    # refuter catch (reproduced): the retired draft stayed PURCHASABLE by id — selling and
    # charging WST after its owner deleted it. Anything not 'active' is not for sale.
    pd = client.post(f"/api/v1/marketplace/listings/{lid}/purchase", json={"quantity": 1})
    assert pd.status_code == 409 and "not offered for sale" in pd.json()["detail"]
    # refuter catch: origin is PROVENANCE — a patch cannot forge 'catalog' onto a user listing
    og = client.patch(f"/api/v1/marketplace/listings/{lid}", json={"origin": "catalog"}).json()
    assert og["origin"] != "catalog"
    # refuter catch: an empty description is a legal stored state — the valuation refuses on
    # the FLOOR (503), never on an innocent empty field (422)
    ve = client.post("/api/v1/marketplace/value", json={"title": "T", "description": ""})
    assert ve.status_code == 503
    _l = _ml(lid); _l.sales_count = 0; _ms(_l)
    d2 = client.delete(f"/api/v1/marketplace/listings/{lid}").json()
    assert d2["deleted"] == lid

    # 6. XAI inputs are bounded to SM-2's actual domain (quality 0-5 etc.)
    assert client.get("/api/v1/qep/xai/explanations?last_quality=99").status_code == 422
    assert client.get("/api/v1/qep/xai/explanations?ease_factor=0.5").status_code == 422
    x = client.get("/api/v1/qep/xai/explanations").json()
    assert "REAL MemorizationEngine" in x["interval_basis"]
    # 7. the compliance audit keeps its tri-state honesty
    a = client.get("/api/v1/qep/compliance/audit").json()
    assert a["compliant"] in (True, False, None) and "never asserted true" in a["note"]

    # 8. an ungoverned organism config key applies DIRECTLY and lands in the history with a
    #    true-under-auth authorship stamp (it was hardcoded "owner-ui-direct" regardless)
    cfg = client.get("/api/v1/organism/config").json()
    k = next(w for w in cfg["key_wiring"] if not w["governed"])
    cur = cfg["config"].get(k["section"], {}).get(k["key"])
    up = client.post("/api/v1/organism/config/update",
                     json={"section": k["section"], "key": k["key"], "value": cur,
                           "reason": f"w444 guard {uid}"})
    assert up.status_code == 200 and up.json()["status"] == "applied"
    hist = client.get("/api/v1/organism/config/history").json()["history"]
    mine = next(h for h in hist if h.get("reason") == f"w444 guard {uid}")
    assert mine["updated_by"] == "owner-ui-direct"   # auth off → the requested default stands
    # 9. the reset guard still refuses to the CCA (surfacing the refusal IS the wiring)
    assert client.post("/api/v1/organism/config/reset", json={}).status_code == 409


def test_w449_floor_served_gate_is_not_assessable_both_ways(client):
    """§10 (delivery-plan P1.1, ledger 1.1) — THE GATE THAT COULD NOT FAIL.

    assure_delivery measured coverage as "declared section names present in the text". The floor
    composes its reply out of the caller's OWN headings, so coverage was 1.0 by construction; on
    Offering-1 it was called with NO sections, so coverage collapsed to a 200-character length check;
    the stub regex never matches the floor's vocabulary. 174 of 174 native deliverables in the store
    were sealed "pass · verified" — a certificate printer. Genesis fixed this class for its own stage
    checks in W436; the SHARED gate every other surface uses never got it.

    Both ways, as rule 4 demands: floor-served → None with the reason, nothing counted as a gate run,
    the record still sealed; the SAME document model-served → pass; with a stub → fail.
    """
    import asyncio as _aio
    from agentic_core.vbs.quality import assure_delivery, floor_served
    loop = _aio.new_event_loop()   # never get_event_loop(): deprecated, and 3.12 raises outside a running loop
    secs = ["Executive Summary", "Background", "Analysis", "Recommendations"]
    doc = "\n".join(
        f"## {s}\n" + (f"A halal artisan bakery in Leeds serving students and families; {s.lower()} "
                       "covers demand, pricing, supply, staffing and the first ninety days. " * 3)
        for s in secs)
    assert len(doc) >= 900

    def gates_run():
        return client.get("/api/v1/vbs/qms/defects").json()["summary"]["gates_run"]

    before = gates_run()
    floor = loop.run_until_complete(assure_delivery(doc, secs, label="w449", served_by="native"))["quality"]
    assert floor["qms_gate_passed"] is None, "a floor-served delivery was certified: %r" % (floor.get("qms_gate_passed"),)
    assert "not assessable" in floor["qms_basis"] and floor["not_assessable"] is True
    c = floor["bar_measured"]["criteria"]
    assert c["verified"]["met"] is None and c["verified"]["source"] == "none" and "not assessable" in c["verified"]["basis"]
    assert c["specifically designed"]["met"] is None and c["specifically designed"]["source"] == "none"
    assert "verified" not in floor["bar_measured"]["measured_criteria"]
    assert floor["document_controlled"] is True and floor["quality_record_hash"]      # still sealed
    assert gates_run() == before, "a not-assessable delivery was counted as a gate run"

    # the SAME document served by a model is assessable — and passes, measured
    model = loop.run_until_complete(assure_delivery(doc, secs, label="w449", served_by="ollama:llama3.2"))["quality"]
    assert model["qms_gate_passed"] is True and model["delivery_coverage"] == 1.0
    v = model["bar_measured"]["criteria"]["verified"]
    assert v["met"] is True and v["source"] == "gate" and "verified" in model["bar_measured"]["measured_criteria"]
    assert gates_run() == before + 1
    # …and the gate can still FAIL on real content
    bad = loop.run_until_complete(assure_delivery(doc + "\nTODO finish", secs, label="w449", served_by="ollama:llama3.2"))["quality"]
    assert bad["qms_gate_passed"] is False
    # the seal is PER DELIVERY now (content hash + server are inside it)
    assert floor["quality_record_hash"] != model["quality_record_hash"] != bad["quality_record_hash"]

    # provenance shapes the gate understands
    assert floor_served("native") and floor_served({"native": 3}) and floor_served(["native", "native"]) and floor_served("template")
    assert not floor_served(None) and not floor_served({"native": 2, "ollama:x": 1}) and not floor_served(["ollama:x"])
    assert not floor_served("verbatim-ingest")   # undeclared origin = the caller's own writing: the gate runs

    # through the API on the floor (this suite): a produced deliverable and a domain tool both say so,
    # and the domain tool's coverage is now measured against the PROMPT's own sections, not None
    d = client.post("/api/v1/deliverables/produce", json={
        "type": "report", "title": "w449 floor", "brief": "a halal artisan bakery in Leeds"}).json()
    q = d["quality_assurance"]["quality"]
    assert q["qms_gate_passed"] is None and "not assessable" in q["qms_basis"]
    law = client.post("/api/v1/law/analyse", json={"document_text": "This agreement is between A and B. " * 20}).json()
    qa = (law.get("ai_provenance") or {}).get("quality_assurance") or {}
    assert qa.get("qms_gate_passed") is None and "not assessable" in (qa.get("qms_basis") or ""), qa

    # refuter F1 — the Genesis page saves the journey VERBATIM as a deliverable. Told only
    # "verbatim-ingest", the gate had certified floor text PASS. Now the ingest carries its origin:
    # floor origin → None (floor basis); no declared origin → the caller's own writing, the gate runs
    # and the basis names verbatim-ingest; a declared model origin → the gate runs under that name.
    v1 = client.post("/api/v1/deliverables/produce", json={
        "type": "report", "title": "w449 verbatim floor", "brief": "b", "content": doc,
        "source_served_by": {"native": 5}}).json()["quality_assurance"]["quality"]
    assert v1["qms_gate_passed"] is None and "floor-served" in v1["qms_basis"], v1
    v2 = client.post("/api/v1/deliverables/produce", json={
        "type": "report", "title": "w449 verbatim unknown", "brief": "b", "content": doc}).json()["quality_assurance"]["quality"]
    assert v2["qms_gate_passed"] is True and "served_by=verbatim-ingest" in v2["qms_basis"], v2
    v3 = client.post("/api/v1/deliverables/produce", json={
        "type": "report", "title": "w449 verbatim model", "brief": "b", "content": doc,
        "source_served_by": "ollama:llama3.2"}).json()["quality_assurance"]["quality"]
    assert v3["qms_gate_passed"] is True and "served_by=ollama:llama3.2" in v3["qms_basis"], v3

    # refuter F2 — the VSB entity never carried ai_provenance, so repo / webapp / mobile ALWAYS fell
    # to the old gate ("QMS gate: PASS … served_by=unspecified" in every shipped QUALITY.md). A
    # journey-born entity now stores the journey's provenance and its shipped body is not assessable
    # on the floor; a standalone /establish (origin unknown) still gets the measured gate.
    j = client.post("/api/v1/genesis/journey", json={
        "problem": "w449 f2: a halal artisan bakery in Leeds serving students", "domain": "enterprise",
        "establish": True, "ship_output": False, "name": "Leeds Student Bakery"}).json()   # W450: named → may publish
    ent = client.get(f"/api/v1/vsb/{j['established_vsb']['vsb_id']}").json()
    assert "native" in (ent.get("ai_provenance") or {}).get("served_by", {}), ent.get("ai_provenance")
    for leg in ("repo", "webapp", "mobile"):
        rq = client.post(f"/api/v1/vsb/{ent['vsb_id']}/{leg}").json()["quality_assurance"]["quality"]
        assert rq["qms_gate_passed"] is None and "floor-served" in rq["qms_basis"], (leg, rq)
    from agentic_core.api.vsb import _REPO_STORE as _RS
    qmd = (_RS / ent["vsb_id"] / "compliance" / "QUALITY.md").read_text(encoding="utf-8")
    assert "NOT ASSESSABLE" in qmd and "QMS gate: PASS" not in qmd, qmd[:600]
    loop.close()


def test_w449_bar_attestations_withheld_on_tie_both_ways(client):
    """§10 (ledger 3.11, R1.4/R2.5) — a ranking that carried no information is not a ranking.

    Genesis attested "modelled · simulated · ranked" as met on runs whose three candidates were
    byte-identical and whose ranking was a tie resolved by list order — while its own basis text said
    "NOT by evidence". Now each is WITHHELD with the reason; with distinct candidates it is attested.
    And the shipped EVIDENCE.md carries the tie note the page already showed.
    """
    from agentic_core.api.genesis import _bar_attestations
    from agentic_core.vbs.quality import _measure_bar

    same = "the same simulation text " * 20
    cands = [{"id": i, "modelled_score": 0.7, "simulation": same, "simulation_score": 0.7,
              "score": 0.8, "score_basis": "form"} for i in ("pragmatic", "innovative", "lean")]
    tie = {"tie": {"detected": True, "resolved_by": "list order — NOT evidence"}, "candidates_distinct": 1,
           "selection_basis": "TIE at 0.8 across 3 candidates — resolved by list order, NOT by evidence. selected pragmatic"}
    ev, wh = _bar_attestations(cands, tie, cands[0], "enterprise", "enterprise", {}, 0)
    four = {"modelled", "ranked", "simulated", "optimised"}
    assert four <= set(wh) and not (four & set(ev)), (ev, wh)
    assert "TIE" in wh["ranked"] and "identical" in wh["simulated"]
    bar = _measure_bar(1.0, False, True, 0.6, {"verdicts": []}, ev, withheld=wh)
    r = bar["criteria"]["ranked"]
    assert r["met"] is None and r["source"] == "none" and "not attested" in r["basis"]
    assert not (four & set(bar["attested_criteria"]))

    # the other way: distinct candidates, distinct twin outputs, no tie → attested
    cands2 = [{**c, "simulation": f"distinct simulation for {c['id']} " * 20,
               "score": 0.9 - 0.1 * i} for i, c in enumerate(cands)]
    ok = {"tie": {"detected": False}, "candidates_distinct": 3, "selection_basis": "selected pragmatic on evidence"}
    ev2, wh2 = _bar_attestations(cands2, ok, cands2[0], "enterprise", "enterprise", {}, 0)
    assert four <= set(ev2) and not (four & set(wh2)), (ev2, wh2)

    # the tie travels to the shipped body: EVIDENCE.md says what the page said
    est = client.post("/api/v1/genesis/establish", json={
        "problem": "w449 tie evidence", "domain": "enterprise", "owner_id": "pytest",
        "selected_candidate": {"id": "pragmatic", "rank": 1, "score": 0.8, "coverage": 1.0,
                               "tie": {"detected": True, "resolved_by": "list order — NOT evidence"},
                               "candidates_distinct": 1}}).json()
    client.post(f"/api/v1/vsb/{est['vsb_id']}/repo")
    from agentic_core.api.vsb import _REPO_STORE
    ev_md = (_REPO_STORE / est["vsb_id"] / "EVIDENCE.md").read_text(encoding="utf-8")
    assert "TIE" in ev_md and "identical text" in ev_md, ev_md


def test_w449_qms_chip_renders_through_one_helper():
    """Rule 26 — a class-kill is only a kill where every site uses the helper. Twenty renderers
    branched on truthiness or `typeof === 'boolean'`; a null verdict would have been amber
    'flagged' on DomainTool and invisible everywhere else. Every chip now routes through qmsChip()."""
    import pathlib
    import re

    src = pathlib.Path("apps/workstation-superapp/src")
    api = (src / "lib" / "api.ts").read_text(encoding="utf-8")
    assert "export const qmsChip" in api and "'not assessable'" in api
    offenders = []
    users = 0
    for f in src.rglob("*.tsx"):
        text = f.read_text(encoding="utf-8", errors="ignore")
        if "qmsChip(" in text:
            users += 1
        for i, line in enumerate(text.splitlines(), 1):
            if re.search(r"qms_gate_passed\s*\?(?!:)", line) or re.search(r"typeof [^\n]*qms_gate_passed[^\n]*=== 'boolean'", line):
                offenders.append(f"{f.relative_to(src)}:{i}")
    assert not offenders, "inline QMS chip logic outside qmsChip(): %s" % offenders
    assert users >= 8, "expected the helper on every chip surface, found %d files" % users


def test_w450_shipped_body_never_wears_scaffold_or_fallback_name(client):
    """§4/§13 (ledger 1.2 · R2.0 R2.1 R2.6 R2.9) — the body a floor journey ships.

    Measured on a live floor entity (W450 audit, :8027): the enterprise was NAMED
    "VSB — I keep 40 beehives in Somerset and lose " (a 40-char cut with a trailing space) on
    every page, manifest, README and the Cockpit; its "concept" on the website, BUSINESS_PLAN.md,
    the app data and the Plan tab was the floor's nine-engine headings (INKASHAF / SAMAJH / SOCH /
    AQAL) over repeated problem bigrams and "Structured … frame for:" archetypes; the footer said
    "quality-gated, compliance-screened"; and "Generate VSB Repository" after the birth-ship
    overwrote the three-page website with a 471-byte scaffold while ship.json said stale=false.

    Both ways: a floor journey → slug name marked pending, ship deferred, the founder names it, the
    body ships the founder's words plus an honest pending state and ZERO engine vocabulary, and
    /repo afterwards leaves the shipped site byte-identical; a model-served establishment (provenance
    declared) ships the concept verbatim with no pending state, and a founder-named one ships at birth.
    """
    import json as _json
    import re as _re
    from agentic_core.api.vsb import _REPO_STORE
    from agentic_core.api import business_plan as bp_mod

    problem = "I keep 40 beehives in Somerset and lose colonies to varroa every winter and cannot afford lab testing"
    j = client.post("/api/v1/genesis/journey", json={
        "problem": problem, "domain": "enterprise", "establish": True, "ship_output": True}).json()
    est = j["established_vsb"]
    vid = est["vsb_id"]
    # the name: a neutral slug, whole words, no prefix, no trailing space — and PENDING
    assert est["name_pending"] is True and est["name_source"] == "slug", est
    assert not est["name"].startswith("VSB") and est["name"] == est["name"].strip() and len(est["name"]) <= 40
    assert est["initial_ship"]["shipped"] is False and est["initial_ship"]["deferred"] == "name pending"
    assert not (_REPO_STORE / f"{vid}.ship.json").exists()          # nothing shipped under a slug
    # refuter F2 — and no publish endpoint ships under the working name either (409 with the way out)
    for leg in ("website", "webapp", "mobile", "board-pack", "repo/ship"):
        r = client.post(f"/api/v1/vsb/{vid}/{leg}")
        assert r.status_code == 409 and "/name" in r.json()["detail"], (leg, r.status_code)
    # the body: every floor-served field is pending, never the floor's text
    ent = client.get(f"/api/v1/vsb/{vid}").json()
    assert all(ent["body_pending"].get(k) for k in ("concept", "design", "commercialisation")), ent["body_pending"]
    assert ent["genesis_blueprint"]["concept"].startswith("content pending the owned model")
    assert "INKASHAF" not in _json.dumps(ent["genesis_blueprint"]) and "INKASHAF" not in ent["ceo_specification"]
    plan = bp_mod._load(vid)
    assert "content pending the owned model" in plan["concept"] and plan["provenance"]["body_pending"]
    assert "native" in (plan["provenance"]["served_by"] or {})

    # the founder names it → the deferred body ships
    named = client.post(f"/api/v1/vsb/{vid}/name", json={"name": "Somerset Hive Health"}).json()
    assert named["name_source"] == "founder" and named["ship"]["shipped"] is True and named["ship"]["coherent_whole"] is True
    ent = client.get(f"/api/v1/vsb/{vid}").json()
    assert ent["name"] == "Somerset Hive Health" and ent["name_pending"] is False
    assert client.post(f"/api/v1/vsb/{vid}/name", json={"name": "x"}).status_code == 422

    # the shipped body: the founder's words, the honest pending state, and NO engine vocabulary
    root = _REPO_STORE / vid
    forbidden = _re.compile(r"_\[|Acting as|native structured|Subject: .*\(domain:|Structured [a-z -]+frame for|"
                            r"Component for |Positioning wedge|Stream from |deterministic scaffold|"
                            r"\bINKASHAF\b|\bSAMAJH\b|\bSOCH\b|\bAQAL\b|VSB — |quality-gated", _re.I)
    body_files = [p for p in root.rglob("*") if p.is_file() and ".git" not in p.parts
                  and p.suffix in (".md", ".html", ".json", ".js", ".webmanifest")]
    assert len(body_files) >= 15, [str(p) for p in body_files]
    hits = {}
    for p in body_files:
        m = forbidden.search(p.read_text(encoding="utf-8"))
        if m:
            hits[str(p.relative_to(root))] = m.group(0)
    assert not hits, f"engine scaffold / fallback name shipped in the body: {hits}"
    index = (root / "web" / "index.html").read_text(encoding="utf-8")
    assert "Somerset Hive Health" in index and "beehives in Somerset" in index
    bplan = (root / "BUSINESS_PLAN.md").read_text(encoding="utf-8")
    assert "beehives in Somerset" in bplan and "content pending the owned model" in bplan
    assert "content pending the owned model" in (root / "web" / "about.html").read_text(encoding="utf-8")
    assert "content pending the owned model" in _json.loads((root / "webapp" / "data.json").read_text(encoding="utf-8"))["concept"]
    pack = client.get("/api/v1/economy/board-pack", params={"vsb_id": vid}).json()
    assert "native structured" not in _json.dumps(pack).lower()
    manifest = _json.loads((root / "mobile" / "manifest.webmanifest").read_text(encoding="utf-8"))
    assert manifest["name"] == "Somerset Hive Health" and manifest.get("icons")

    # re-generating the repo after the ship never regresses the shipped site, and the ship is honest
    before = (root / "web" / "index.html").read_bytes()
    m2 = client.post(f"/api/v1/vsb/{vid}/repo").json()
    assert (root / "web" / "index.html").read_bytes() == before
    assert "generated" in m2["integrated_surfaces"]["website"] and "web/index.html" not in m2["tree"]
    ship = _json.loads((_REPO_STORE / f"{vid}.ship.json").read_text(encoding="utf-8"))
    assert ship["stale"] is False and ship["surfaces"]["website"]["file_count"] == 3
    # …and renaming a SHIPPED body marks it stale with the reason (its every page wears the name),
    # and the delivery swarm the body ships follows the name (refuter F4)
    r2 = client.post(f"/api/v1/vsb/{vid}/name", json={"name": "Somerset Hive Health Ltd"}).json()
    assert r2["ship"]["marked_stale"] is True
    ent = client.get(f"/api/v1/vsb/{vid}").json()
    assert ent["native_swarm"]["name"] == "Somerset Hive Health Ltd — delivery swarm"
    assert bp_mod._load(vid)["provenance"]["name_source"] == "founder"
    ship = _json.loads((_REPO_STORE / f"{vid}.ship.json").read_text(encoding="utf-8"))
    assert ship["stale"] is True and "renamed" in ship["stale_reason"]

    # the other way: a model-served establishment (provenance declared) ships its concept VERBATIM,
    # nothing pending; a founder-named one ships at birth
    concept = "CONCEPT-W450-XRAY a mobile varroa lab van serving Somerset beekeepers by subscription"
    e2 = client.post("/api/v1/genesis/establish", json={
        "problem": problem, "domain": "enterprise", "name": "Varroa Van", "concept": concept,
        "design": "a van, a microscope, a route", "commercialisation": "monthly subscription per apiary",
        "ship_output": True,
        "ai_provenance": {"served_by": {"ollama:llama3.2": 11}, "any_external": False,
                          "served_by_agent": {"genesis_concept": "ollama:llama3.2", "genesis_design": "ollama:llama3.2",
                                              "genesis_commercial": "ollama:llama3.2"}}}).json()
    assert e2["name_source"] == "founder" and e2["name_pending"] is False and e2["initial_ship"]["shipped"] is True
    assert not any(e2["body_pending"].values()), e2["body_pending"]
    bp2 = (_REPO_STORE / e2["vsb_id"] / "BUSINESS_PLAN.md").read_text(encoding="utf-8")
    assert "CONCEPT-W450-XRAY" in bp2 and "content pending" not in bp2
    # a standalone establishment with NO provenance is the caller's own writing — shipped as given
    e3 = client.post("/api/v1/genesis/establish", json={
        "problem": "w450 caller words", "concept": "CALLER-W450-CONCEPT", "ship_output": False}).json()
    assert not any(e3["body_pending"].values()) and e3["name_source"] in ("model", "slug")   # refuter F3: precedence
    assert client.get(f"/api/v1/vsb/{e3['vsb_id']}").json()["genesis_blueprint"]["concept"] == "CALLER-W450-CONCEPT"


def test_w450_spawn_seam_shares_the_name_and_body_rule(client):
    """Refuter F1 — /api/v1/vsb/spawn (reached from the Spawn Studio) still wrote `VSB — {challenge[:60]}`
    and stored the floor's raw output as the CEO specification. Same rule as Genesis: a pending slug
    that publishes nothing, a pending CEO spec on the floor; a founder-named spawn is not pending."""
    import json as _json
    from agentic_core.api.genesis import _slug_name
    r = client.post("/api/v1/vsb/spawn", json={"challenge": "w450 spawn: a halal artisan bakery in Leeds serving students"})
    done = [_json.loads(l[6:]) for l in r.text.splitlines() if l.startswith("data: ")]
    fin = [e for e in done if e.get("stage") == "complete"][-1]["data"]
    assert fin["name_pending"] is True and not fin["name"].startswith("VSB")
    ent = client.get(f"/api/v1/vsb/{fin['vsb_id']}").json()
    assert ent["body_pending"]["ceo_specification"] is True
    assert ent["ceo_specification"].startswith("content pending the owned model")
    assert "native structured" not in ent["ceo_specification"].lower()
    assert client.post(f"/api/v1/vsb/{fin['vsb_id']}/website").status_code == 409
    r2 = client.post("/api/v1/vsb/spawn", json={"challenge": "w450 named spawn", "name": "Leeds Halal Bakery"})
    fin2 = [_json.loads(l[6:]) for l in r2.text.splitlines() if l.startswith("data: ") and '"complete"' in l][-1]["data"]
    assert fin2["name"] == "Leeds Halal Bakery" and fin2["name_pending"] is False
    # the slug itself: whole words only, letters only, never a mid-word cut
    assert _slug_name("Pneumonoultramicroscopicsilicovolcanoconiosis treatment clinic") == "Treatment Clinic"
    assert _slug_name("I've been thinking about bees") == "Been Thinking Bees"
    assert len(_slug_name("x")) >= 3 and " " not in _slug_name("").strip() or _slug_name("") == "Venture"


def test_w451_ceo_chat_runs_on_the_owned_fabric_both_ways(client, monkeypatch):
    """§5 / ledger 1.3 (R3.0 R4.0) — the default tab of the Living Organisation hub was a detached
    roleplay: /api/v138/ceo/chat opened its own httpx stream to a hard-coded llama3.2 as "the AI CEO
    of the Galactic Era" (invented constitutional articles and debates — measured live: a 56-second
    "Galactic Council" answer on a backend whose every owned surface said deterministic_floor),
    ignoring AI_DISABLE_LOCAL, the breaker, guardrails, tenant memory and provenance; registered a
    lambda "tool" on cue; and streamed a canned "[Offline Mode] … sovereign mesh advisory" one
    character per 8 ms under a pill hard-wired to "Planetary Strategy Active".

    Both ways: on the floor the terminal frame says served_by=native (the page renders amber) and the
    answer is grounded in the Board/plan, with none of the roleplay vocabulary; with the owned model
    serving (substituted at the one seam) the terminal frame names the model. gateway.stream keeps
    its token-only shape for its three older consumers.
    """
    import asyncio as _aio
    import json as _json
    import os as _os
    from pathlib import Path as _P
    from agentic_core.ai.gateway import gateway, ModelGateway

    def events(text):
        return [_json.loads(l[6:]) for l in text.splitlines() if l.startswith("data: ")]

    r = client.post("/api/v138/ceo/chat", json={"message": "What should we prioritise this quarter?"})
    assert r.status_code == 200 and r.headers["content-type"].startswith("text/event-stream")
    evs = events(r.text)
    fin = evs[-1]
    assert fin["done"] is True and fin["served_by"] == "native" and fin["is_external"] is False, fin
    assert fin["grounding"]["scope"] == "workstation" and "directives" in fin["grounding"]
    body = "".join(e.get("content", "") for e in evs)
    assert body.strip() and "[Offline Mode]" not in body and "Galactic" not in body and "sovereign mesh" not in body
    assert not any("served_by" in e for e in evs[:-1])          # provenance is the terminal frame, once
    # refuter F1 — the SECOND turn: the page posts its messages back as context, and after the first
    # answer they carry servedBy / isExternal / grounding — a str-typed context 422'd every second turn
    r2t = client.post("/api/v138/ceo/chat", json={"message": "and the risks?", "context": [
        {"role": "user", "content": "What should we prioritise this quarter?"},
        {"role": "assistant", "content": body, "servedBy": "native", "isExternal": False,
         "grounding": fin["grounding"]}]})
    assert r2t.status_code == 200 and events(r2t.text)[-1]["served_by"] == "native"
    # refuter F6 — a scope the caller does not own is 404, never summarised into the model input
    assert client.post("/api/v138/ceo/chat", json={"message": "x", "scope": "vsb-not-mine-000"}).status_code == 404
    # refuter F4 — the living-plan fact is real, not a dead None
    assert isinstance(fin["grounding"]["plan_score"], float)
    # the roleplay seams are gone: no lambda tool registration route, no own httpx stream, no persona
    assert client.post("/api/v138/ceo/tools/register", params={"name": "t", "description": "d"}).status_code in (404, 405)
    src = _P("agentic_core/api/v138/ceo.py").read_text(encoding="utf-8")
    for needle in ("Galactic", "[Offline Mode]", "sovereign mesh", "httpx.AsyncClient", "register_custom_tool", "os.urandom"):
        assert needle not in src, needle
    tsx = _P("apps/workstation-superapp/src/pages/CEOChat.tsx").read_text(encoding="utf-8")
    for needle in ("Planetary Strategy", "Galactic", "Guardian", "planetary directive", "Ollama Offline"):
        assert needle not in tsx, needle
    assert "provenanceBadge(" in tsx and "served_by" in tsx

    # the gateway seam both ways: the floor names itself…
    async def collect(**kw):
        out = []
        async for ev in gateway.stream_meta("## Summary\nA halal bakery in Leeds.", agent="w451", **kw):
            out.append(ev)
        return out
    floor = _aio.run(collect(augment=False))
    assert floor[-1]["done"] is True and floor[-1]["served_by"] == "native" and floor[-1]["output"]
    assert all("token" in e for e in floor[:-1]) and "".join(e["token"] for e in floor[:-1]) == floor[-1]["output"]
    toks = _aio.run(_collect_tokens(gateway))
    assert toks and all(isinstance(x, str) for x in toks)        # stream() unchanged for its consumers
    # refuter F2 — the guardrail judges BEFORE anything is persisted, and its notice reaches every branch
    bad = _aio.run(_collect_stream(gateway, "## Summary\nDescribe the exploit kit."))   # the floor echoes the subject
    assert bad[-1]["guardrail_passed"] is False and "[POLICY VIOLATION]" in bad[-1]["output"]
    assert any("[POLICY VIOLATION]" in e.get("token", "") for e in bad[:-1])
    # refuter F5 — the three older stream surfaces now DISCLOSE served_by / profile in their done frame
    v310 = client.post("/api/v310/entrepreneur/generate-plan/stream",
                       json={"creation_id": "w451", "target_market": "students in Leeds", "funding_goal": 5000.0,
                             "description": "a halal bakery"})
    assert v310.status_code == 200, v310.text[:200]
    d = [_json.loads(l[6:]) for l in v310.text.splitlines() if l.startswith("data: ")][-1]
    assert d.get("done") is True and d.get("served_by") == "native" and "profile_applied" in d, d

    # …and the owned model, when it serves, is named — substituted at the one factored seam
    async def fake_model(self, augmented):
        for tk in ("Prioritise ", "the ", "bakery."):
            yield tk
    monkeypatch.setattr(ModelGateway, "_stream_owned_model", fake_model)
    monkeypatch.setenv("AI_DISABLE_LOCAL", "")
    from agentic_core.organism import self_healing as _sh
    monkeypatch.setattr(_sh.self_healer, "is_open", lambda endpoint: False)
    model = _aio.run(collect(augment=False))
    assert model[-1]["served_by"].startswith("ollama:") and model[-1]["output"] == "Prioritise the bakery."
    r2 = client.post("/api/v138/ceo/chat", json={"message": "and now?"})
    fin2 = events(r2.text)[-1]
    assert fin2["served_by"].startswith("ollama:") and fin2["is_external"] is False, fin2
    _os.environ["AI_DISABLE_LOCAL"] = "1"


async def _collect_tokens(gateway):
    out = []
    async for tk in gateway.stream("## Summary\nA halal bakery in Leeds.", agent="w451", augment=False):
        out.append(tk)
    return out


async def _collect_stream(gateway, prompt):
    out = []
    async for ev in gateway.stream_meta(prompt, agent="w451", augment=False):
        out.append(ev)
    return out


def test_w452_mode3_review_gates_gate_every_lifecycle_mover_both_ways(client):
    """§17.4 Mode 3 (ledger 1.4 · R2.2 R3.1) — the review gate was a record, not a gate.

    Measured live (W452 baseline, :8032): with the design gate REJECTED, ship, evolve, the repo
    cascade, plan orchestration, the entity's own delivery-swarm run and a fresh establish all
    returned 200 — byte for byte the same as with the gate approved or absent; `blocks_progress`
    had one reader, its own GET endpoint, whose docstring promised the lifecycle honoured it.

    Both ways: a pending or rejected gate → 409 {gate, status, blocks_progress} on EVERY mover and
    the heartbeat's autonomous movers hold with a recorded action; approved (or ungated) → 200;
    a gate set at birth holds the birth-ship with the gate named; an entity with no gates is untouched.
    """
    import asyncio as _aio
    import json as _json
    from agentic_core.config import data_path

    def establish(name, **extra):
        return client.post("/api/v1/genesis/establish", json={
            "problem": "w452 gates: a halal bakery in Leeds", "name": name, "concept": "a bakery",
            "design": "ovens and a route", "commercialisation": "subscriptions", "ship_output": False, **extra}).json()

    e = establish("Gate Probe Bakery")
    vid = e["vsb_id"]
    client.post(f"/api/v1/vsb/{vid}/repo").json()                      # a repo exists for the cascade leg
    cascade_id = client.get(f"/api/v1/vsb/{vid}").json()["native_swarm"]["cascade_id"]
    oid = client.get("/api/v1/business-plan", params={"scope": vid}).json()["objectives"][0]["id"]

    def movers():
        return {
            "ship": client.post(f"/api/v1/vsb/{vid}/repo/ship"),
            # refuter F3 — the ship's parts are movers too (the Genesis card exposes all five)
            "repo": client.post(f"/api/v1/vsb/{vid}/repo"),
            "website": client.post(f"/api/v1/vsb/{vid}/website"),
            "web app": client.post(f"/api/v1/vsb/{vid}/webapp"),
            "phone app": client.post(f"/api/v1/vsb/{vid}/mobile"),
            "board pack": client.post(f"/api/v1/vsb/{vid}/board-pack"),
            "evolve": client.post(f"/api/v1/vsb/{vid}/evolve", json={"trigger": "w452"}),
            "evolution apply": client.post(f"/api/v1/vsb/{vid}/evolution/apply"),
            "repo cascade": client.post(f"/api/v1/vsb/{vid}/repo/cascade", json={"mission": "w452"}),
            "cascade": client.post("/api/v1/swarm/cascade", json={"mission": "w452 org cascade", "scope": vid}),
            "swarm run": client.post("/api/v1/resources/swarm/run", json={"swarm_id": cascade_id}),
            "orchestrate": client.post(f"/api/v1/business-plan/objective/{oid}/orchestrate", json={"scope": vid}),
        }

    # gate the design stage: PENDING blocks (a human has been asked; nothing moves until they answer)
    assert client.post(f"/api/v1/vsb/{vid}/review-gates", json={"stages": ["design"]}).status_code == 200
    for mover, r in movers().items():
        assert r.status_code == 409, (mover, r.status_code, r.text[:200])
        d = r.json()["detail"]
        assert d["gate"] == "design" and d["status"] == "pending" and d["blocks_progress"] is True and d["mover"] == mover, (mover, d)
        assert "/review-gates/design/decision" in d["clear_by"]
    # REJECTED blocks too, and says so
    client.post(f"/api/v1/vsb/{vid}/review-gates/design/decision", json={"decision": "reject", "note": "not yet"})
    r = client.post(f"/api/v1/vsb/{vid}/repo/ship")
    assert r.status_code == 409 and r.json()["detail"]["status"] == "rejected"
    # the heartbeat's autonomous movers HOLD with a recorded action instead of a silent except-pass
    from agentic_core.api.vsb import _REPO_STORE, mark_repo_stale
    ship_p = _REPO_STORE / f"{vid}.ship.json"
    ship_p.write_text(_json.dumps({"vsb_id": vid, "shipped": True, "stale": False, "surfaces": {}}), encoding="utf-8")
    assert mark_repo_stale(vid, "w452 drift")
    from agentic_core.organism.heartbeat import heartbeat as _hb
    _prev = (_hb.auto_ship, _hb.auto_evolve) if hasattr(_hb, "auto_evolve") else (_hb.auto_ship, None)
    _hb.auto_ship = True
    try:
        beat = _aio.run(_hb.beat()) if _aio.iscoroutinefunction(_hb.beat) else _hb.beat()
    finally:
        _hb.auto_ship = _prev[0]
    acts = (beat or {}).get("actions") if isinstance(beat, dict) else None
    acts = acts if acts is not None else getattr(_hb, "last_actions", [])
    assert any(a == f"reship_held_by_review_gate:{vid}" for a in acts), acts
    # (the recorded hold is the evidence — an older stale repo from another test could keep this
    # stale flag true on its own; the flag is a consistency check, not the proof)
    assert _json.loads(ship_p.read_text(encoding="utf-8"))["stale"] is True
    # refuter F2 — the FUNCTION the heartbeat's auto-apply lever calls holds too, not only the endpoint
    from agentic_core.api.vsb import apply_approved_evolution
    held = apply_approved_evolution(vid)
    assert held["applied"] is False and held["reason"] == "review_gate_blocks" and "design" in held["detail"]

    # the other way: APPROVED clears every mover (200), and an UNGATED entity is untouched
    client.post(f"/api/v1/vsb/{vid}/review-gates/design/decision", json={"decision": "approve", "note": "go"})
    for mover, r in movers().items():
        assert r.status_code == 200, (mover, r.status_code, r.text[:200])
    e2 = establish("Ungated Bakery")
    assert client.post(f"/api/v1/vsb/{e2['vsb_id']}/repo/ship").status_code == 200

    # a gate set AT BIRTH holds the birth-ship with the gate named; a bad stage id is refused
    e3 = establish("Born Gated Bakery", ship_output=True, review_gates=["design"])
    assert e3["initial_ship"]["shipped"] is False and e3["initial_ship"]["deferred"] == "review gate"
    assert e3["initial_ship"]["gate"] == "design" and e3["initial_ship"]["status"] == "pending"
    assert not (_REPO_STORE / f"{e3['vsb_id']}.ship.json").exists()
    assert client.get(f"/api/v1/vsb/{e3['vsb_id']}/review-gates/design").json()["blocks_progress"] is True
    assert client.post("/api/v1/genesis/establish", json={"problem": "x", "name": "Bad Gate", "review_gates": ["nope"]}).status_code == 400
    # refuter F1 — the SSE path refuses a bad stage id with a REAL 400 (it had been an empty 200 stream)
    rs = client.post("/api/v1/genesis/establish/stream", json={"problem": "x", "name": "Bad Gate", "review_gates": ["nope"]})
    assert rs.status_code == 400 and "unknown review-gate stage" in rs.text
    # …and the journey path forwards the gates
    j = client.post("/api/v1/genesis/journey", json={"problem": "w452 journey gates", "name": "Journey Gated",
                                                     "establish": True, "ship_output": True, "review_gates": ["launch"]}).json()
    assert j["established_vsb"]["initial_ship"]["deferred"] == "review gate" and j["established_vsb"]["initial_ship"]["gate"] == "launch"

def test_w453_every_provenance_badge_routes_through_the_helper():
    """Ledger 1.5 (R5.1 R3.4 R3.7) — TEN BADGE SITES PAINTED THE FLOOR GREEN. provenanceBadge() has said
    amber "structured floor — not model analysis" since W439, but eight sites took only its .label and
    coloured the chip by is_external (emerald unless external — so the floor wore green), MyWork wrote
    'in-house' emerald with no floor label, Generator and OrganismAnatomy chipped by is_external, and
    BoardOfDirectors / SwarmIntelligence / ReactorStudio / ResourceFabric inlined their own
    'in-house / external used' chips over provenance MAPS (green when every call was the floor).

    Rule 26 — a class-kill is only a kill where every site uses the helper: every site now renders
    the helper's cls/title (provenanceBadge for a string, provenanceMapBadge for a count map). This
    guard fails on `.label` taken without `.cls`, on any inline is_external / any_external / served_by
    === "native" colour ternary, and on the helpers being fewer than the sites they replaced.
    """
    import re
    from pathlib import Path
    src = Path("apps/workstation-superapp/src")
    files = [p for p in src.rglob("*.tsx")] + [p for p in src.rglob("*.ts")]
    label_only, ternaries, users = [], [], set()
    for p in files:
        text = p.read_text(encoding="utf-8")
        if ("provenanceBadge(" in text or "provenanceMapBadge(" in text) and p.name != "api.ts":
            users.add(p.name)   # renderers only — the helper's own file is not a user (refuter F7)
        for i, line in enumerate(text.splitlines(), 1):
            if re.search(r"provenanceBadge\(.*?\)\.label", line) or re.search(r"provenanceMapBadge\(.*?\)\.label", line):
                label_only.append(f"{p.name}:{i}")
            # a COLOUR ternary over provenance: a tailwind class, a tone/colour prop, or a JSX icon as the
            # consequent (refuter F2: the first cut matched only bare classes and missed Chip tone= /
            # Badge color= / icon-swap shapes). Text-only suffixes (' · external used') are not the class.
            if re.search(r"(is_external|isExternal|any_external)\s*\?\s*('(bg-|text-|border-|warn|ok|amber|emerald)|<)", line) \
                    or re.search(r"served_by === 'native' \?\s*('(bg-|text-|border-|warn|ok|amber|emerald)|<)", line) \
                    or re.search(r"served_by\['native'\][^?]*\?\s*'(bg-|text-|border-)", line):
                ternaries.append(f"{p.name}:{i}: {line.strip()[:100]}")
    assert not label_only, f"badge label taken without its cls/title: {label_only}"
    assert not ternaries, f"inline provenance colouring outside the helper: {ternaries}"
    assert len(users) >= 18, f"expected the helpers on every badge surface, found {sorted(users)}"
    api = (src / "lib" / "api.ts").read_text(encoding="utf-8")
    assert api.count("export const provenanceMapBadge") == 1 and "return provenanceBadge('native')" in api


def test_w454_employment_default_tab_is_honest(client, monkeypatch):
    """Ledger 1.6 (R5.0) — the Employment hub opened on the Application Studio, whose Job Search Engine
    said "Live, real-time search across public job boards" over a route whose own docstring said "not a
    live job board" and whose prompt asked the model to invent a URL and a posting date per listing —
    rendered as links; "sources_used" named the synthesis as a source; generated documents rendered
    with no provenance.

    Both ways: the route returns ILLUSTRATIVE listings (no url, no published, salary labelled an
    estimate, illustrative=True, sources_used empty, a basis sentence, provenance); the hub opens on
    the CV tools; the page's copy and rendering carry none of the old claims (source grep) and render
    provenance on the search and on every generated document; a legacy 'use' call still works.
    """
    from pathlib import Path
    r = client.post("/api/v1/career/job-search", json={"query": "halal bakery operations manager Leeds", "limit": 3}).json()
    assert r["illustrative"] is True and r["sources_used"] == [] and "not a live job board" in r["basis"]
    assert r["ai_provenance"]["served_by"] in ("native", "ollama") or str(r["ai_provenance"]["served_by"]).startswith("ollama:")
    for row in r["results"]:
        assert "url" not in row and "published" not in row and "source" not in row, row
        assert row["illustrative"] is True and row["listing_id"] and "not a live advert" in row["basis"]
    # the floor emits no JSON rows, so the loop above is empty on the floor (the first break-test of this
    # guard PASSED with a fabricated url put back — vacuous). Substitute a model that IGNORES the prompt
    # and invents a url, a date and a source: the route must still ship none of them.
    from agentic_core.api import career as _career
    async def _model_that_invents(prompt, agent, **kw):
        return ('{"title": "Ops Manager", "company": "Bakehouse", "location": "Leeds", "url": "https://invented.example/job", '
                '"published": "2026-01-01", "salary": "£32k", "source": "Indeed", "tags": ["ops"], "description": "d"}',
                {"posture": "in-house-first", "served_by": "ollama:test", "is_external": False})
    monkeypatch.setattr(_career, "ai_text", _model_that_invents)
    r2 = client.post("/api/v1/career/job-search", json={"query": "ops", "limit": 3}).json()
    assert len(r2["results"]) == 1, r2
    row = r2["results"][0]
    assert "url" not in row and "published" not in row and "source" not in row, row
    assert row["salary_estimate"] == "£32k" and row["illustrative"] is True and row["listing_id"]
    assert r2["ai_provenance"]["served_by"] == "ollama:test" and r2["sources_used"] == []
    # refuter F1 — 'use' had persisted NOTHING behind a green "Set as Target Job Ad": it attaches now
    before = len(client.get("/api/v1/ingest/list", params={"category": "job_ad"}).json())
    used = client.post("/api/v1/career/job-search/use", json={"listing_id": "abc123", "title": "Ops Manager",
                                                               "company": "Bakehouse", "location": "Leeds",
                                                               "description": "Run the bakery.", "salary_estimate": "£32k"}).json()
    assert used["status"] == "attached" and used["illustrative"] is True and used["file_id"]
    ads = client.get("/api/v1/ingest/list", params={"category": "job_ad"}).json()
    assert len(ads) == before + 1 and "ILLUSTRATIVE" in ads[-1]["extracted_text"] and "Ops Manager" in ads[-1]["extracted_text"]
    assert client.post("/api/v1/career/job-search/use", json={"listing_id": "x"}).status_code == 422   # nothing to attach
    # the prompt no longer asks for a url or a date
    src = Path("agentic_core/api/career.py").read_text(encoding="utf-8")
    assert '"url": "https://...' not in src and '"published": "2026' not in src and "do not invent employers' web addresses" in src
    # the page: no live-board claim, no fabricated link, ids not urls, provenance rendered; the hub opens on the CV tools
    tsx = Path("apps/workstation-superapp/src/components/employment/ApplicationStudio.tsx").read_text(encoding="utf-8")
    for needle in ("Live, real-time search", "No live listings", "sources_used", "listing.url", "href={listing.url}", "listing.published"):
        assert needle not in tsx, needle
    assert "not a live job board" in tsx and "illustrative · no live URL" in tsx and tsx.count("provenanceBadge(") >= 2
    hub = Path("apps/workstation-superapp/src/pages/domains/EmploymentHub.tsx").read_text(encoding="utf-8")
    assert "get('tab') || 'cv'" in hub and "get('tab') || 'studio'" not in hub
    # the other way: the CV tool on the new default tab still generates with provenance
    cv = client.post("/api/v1/employment/cv", json={"target_role": "Bakery operations manager", "experience": "five years running a halal bakery in Leeds", "skills": ["operations", "food safety"], "seniority": "mid"}).json()
    assert (cv.get("ai_provenance") or {}).get("served_by"), cv


def test_w455_compliance_reads_what_it_can_and_says_what_it_cannot(client, monkeypatch):
    """Ledger 1.7 (R1.1 R1.3 R1.6) — the constitutional row could not read content (gaas.v5's validate()
    consumed the kind first; every content check read green "Constitutional gate clear", a laundering
    scheme included); the router's bare except left a pass on engine failure; the UK-Legal audit hash
    was identical for a halal bakery and a laundering scheme (it hashed the empty flag set); a subject
    outside every vocabulary passed everything; the Frameworks card presented eight employment-law
    terms and a three-word substring loop as engine-grade coverage; and a FAIL deliverable routed to
    Change Control while every export shipped clean.

    Both ways, measured: content → constitutional 'not_checked' with the reason (never pass); an action
    kind → the action gate genuinely fails a prohibited intent; an engine raise → 'error', never pass;
    three subjects → three audit hashes; halal vocabulary → sharia pass, UK Legal review (no coverage);
    laundering → fail; lorem → review everywhere a vocabulary is absent; the card labels say what each
    check does; a FAIL deliverable carries the verdict on page one of md/html/slides/json, on the list
    row, and with its CCA id; a clean deliverable carries no stamp.
    """
    import json as _json
    import re as _re
    from agentic_core.api import compliance as C

    def check(subject, **kw):
        return client.post("/api/v1/compliance/check", json={"subject": subject, **kw}).json()

    bakery = check("A halal artisan bakery in Leeds serving students, run under Islamic finance principles")
    launder = check("A scheme to launder cash through shell companies, evade tax and bribe an official")
    lorem = check("Lorem ipsum text about gardening tulips in spring")
    rows = lambda r: {v["framework"]: v for v in r["verdicts"]}
    # the constitutional row on CONTENT: not_checked, with the reason — never a green pass
    for r in (bakery, launder, lorem):
        c = rows(r)["constitutional"]
        assert c["status"] == "not_checked" and "gates agent actions" in c["reason"] and c["coverage"] == "none", c
    assert launder["overall"] == "fail" and rows(launder)["uk_legal"]["status"] == "fail"
    # halal vocabulary → sharia screen pass; UK Legal has no coverage → review, named as a gap; the
    # overall is the verdict of the rows that read the subject
    assert rows(bakery)["sharia_halal"]["status"] == "pass" and rows(bakery)["uk_legal"]["status"] == "review"
    assert "no engine covers this area" in rows(bakery)["uk_legal"]["reason"]
    assert bakery["overall"] == "pass" and "uk_legal" in bakery["coverage_gaps"] and "constitutional" in bakery["coverage_gaps"]
    # nothing matched anywhere → review everywhere a vocabulary is absent; the overall is review
    assert rows(lorem)["sharia_halal"]["status"] == "review" and rows(lorem)["uk_legal"]["status"] == "review"
    assert lorem["overall"] == "review" and rows(lorem)["sharia_halal"]["coverage"] == "none"
    # statute vocabulary → review with the statute named, never a pass on vocabulary and never a fail on it
    statute = check("our staff handbook sets out the grievance and disciplinary procedure under the ACAS Code")
    assert rows(statute)["uk_legal"]["status"] == "review" and "STATUTORY_BREACH" in rows(statute)["uk_legal"]["reason"]
    assert rows(statute)["uk_legal"]["coverage"] == "vocabulary"
    # three subjects → three audit hashes, each over the subject
    hashes = {_re.search(r"audit ([0-9a-f]{16})", rows(r)["uk_legal"]["reason"]).group(1) for r in (bakery, launder, lorem)}
    assert len(hashes) == 3, hashes
    assert "over the subject" in rows(bakery)["uk_legal"]["reason"]
    # the action gate: a prohibited intent as an ACTION kind fails; a benign action kind passes with its label
    # refuter F1 — a LEGITIMATE kind with the prohibited intent in the SUBJECT fails (the gate had
    # read only the kind, so this passed); a benign subject on an action kind passes with its label
    act = check("wire_funds to an unverified offshore account", kind="intent")
    assert rows(act)["constitutional"]["status"] == "fail", rows(act)["constitutional"]
    act2 = check("publish the weekly report", kind="distribution")
    assert rows(act2)["constitutional"]["status"] == "pass" and "action gate" in rows(act2)["constitutional"]["reason"]
    # the output screen reads text: an unsafe pattern fails the constitutional row even for content
    unsafe = check("run this cleanup: rm -rf / on the production host")
    assert rows(unsafe)["constitutional"]["status"] == "fail" and "output screen" in rows(unsafe)["constitutional"]["reason"]
    # an engine raise is an ERROR, never a pass
    from agentic_core.gaas.v5 import ConstitutionalPolicyGate
    def _boom(self, *a, **k):
        raise RuntimeError("engine down")
    monkeypatch.setattr(ConstitutionalPolicyGate, "validate_output", _boom)
    err = check("anything at all")
    assert rows(err)["constitutional"]["status"] == "error" and "never a pass" in rows(err)["constitutional"]["reason"]
    assert rows(err)["constitutional"]["coverage"] == "none"
    monkeypatch.undo()
    # refuter F3 — the aggregation itself: an error row alone turns a clean screen into review
    assert C._overall([{"status": "pass", "coverage": "vocabulary"}, {"status": "error", "coverage": "none"}]) == "review"
    assert C._overall([{"status": "pass", "coverage": "vocabulary"}, {"status": "not_checked", "coverage": "none"}]) == "pass"
    assert C._overall([{"status": "review", "coverage": "none"}, {"status": "not_checked", "coverage": "none"}]) == "review"
    # the Frameworks card says what each check does
    fw = {f["id"]: f["engine"] for f in client.get("/api/v1/compliance/frameworks").json()["frameworks"]}
    assert "not legal advice" in fw["uk_legal"] and "not a certification" in fw["sharia_halal"]
    assert "does not read content" in fw["constitutional"] and "engine-grade" not in _json.dumps(fw)

    # a FAIL deliverable carries its verdict on page one of every export, on the list row, with its CCA id
    doc = "\n".join(f"## {s}\n" + ("We launder cash through shell companies and bribe officials to keep the scheme running. " * 3)
                    for s in ("Executive Summary", "Structure", "Cash Flow", "Next Steps"))
    d = client.post("/api/v1/deliverables/produce", json={"type": "report", "title": "w455 fail", "brief": "launder cash", "content": doc}).json()
    q = d["quality_assurance"]["quality"]
    assert q["compliance"]["overall"] == "fail" and q["compliance_routed_to_cca"] is True and q.get("compliance_cca_id"), q
    for fmt in ("md", "html", "slides", "txt", "svg"):
        body = client.get(f"/api/v1/deliverables/{d['id']}/export", params={"format": fmt}).text
        head = body[:1500]                                          # page one, not a footer
        assert "COMPLIANCE VERDICT: FAIL" in head and "NOT cleared for use" in head, (fmt, head[:300])
        assert q["compliance_cca_id"] in head, fmt                  # svg truncates the sub line — the id still leads
    assert "uk_legal" in client.get(f"/api/v1/deliverables/{d['id']}/export", params={"format": "txt"}).text[:1500]   # F8
    js = _json.loads(client.get(f"/api/v1/deliverables/{d['id']}/export", params={"format": "json"}).text)
    assert "COMPLIANCE VERDICT: FAIL" in js["compliance_stamp"] and js["compliance_cca_id"] == q["compliance_cca_id"]
    assert js["compliance"]["overall"] == "fail"
    row = next(x for x in client.get("/api/v1/deliverables").json()["deliverables"] if x["id"] == d["id"])
    assert row["compliance_overall"] == "fail"
    # the other way: a clean deliverable carries no stamp
    clean = "\n".join(f"## {s}\n" + ("A halal artisan bakery in Leeds serving students; the plan covers demand, pricing and supply. " * 3)
                      for s in ("Executive Summary", "Market", "Operations", "Next Steps"))
    d2 = client.post("/api/v1/deliverables/produce", json={"type": "report", "title": "w455 clean", "brief": "bakery", "content": clean}).json()
    assert d2["quality_assurance"]["quality"]["compliance"]["overall"] != "fail"
    assert "COMPLIANCE VERDICT" not in client.get(f"/api/v1/deliverables/{d2['id']}/export", params={"format": "md"}).text


def test_w456_tafsir_tab_completes_section_11_both_ways(client, monkeypatch):
    """§11 rules 2/4/5 (ledger 1.8 · R1.0) — the tafsir tab served a floor "## Translation" section over
    sacred text: rule 4 (a translation must come from a model) was applied at /qep/translation (503) and
    not here; the response carried the sourced Arabic, its source, the reference and the range cap, and
    the tab rendered none of them (DomainTool showed resultKey + disclaimer only — and there was no
    disclaimer key).

    Both ways: on the floor the Transliteration and Translation sections are WITHHELD (named), a
    floor_note says why, the disclaimer is present, the Arabic source line is present, 2:1-20 is capped
    with the range note; a model-served tafsir (substituted at ai_text) keeps its Translation section
    and carries no floor_note. The tab renders the Arabic, source, reference, range note and floor note.
    """
    from pathlib import Path
    from agentic_core.api import religion as R
    from agentic_core.api.religion import _withhold_sections

    # the cutter both ways
    txt = "## Transliteration (of the provided text only)\nbismi\n## Translation (AI-assisted)\nIn the name\n## Exegesis\nreal notes\n"
    out, removed = _withhold_sections(txt, ("Transliteration", "Translation"))
    assert removed == ["Transliteration", "Translation"] and "## Exegesis" in out and "Translation" not in out and "bismi" not in out
    assert _withhold_sections("## Exegesis\nonly", ("Translation",)) == ("## Exegesis\nonly", [])

    # on the floor (this suite): the prompt never ASKS for a translation (nothing to cut, nothing in
    # memory), the sections are named as withheld, noted, disclaimed; the source line; the range cap
    seen = {}
    _real_ai_text = R.ai_text
    async def _spy(prompt, agent, **kw):
        seen["prompt"] = prompt
        return await _real_ai_text(prompt, agent, **kw)
    monkeypatch.setattr(R, "ai_text", _spy)
    assert R._model_available() is False                      # the floor: no model resource here
    tf = client.post("/api/v1/religion/quran-tafsir", json={"surah": 2, "ayah_start": 1, "ayah_end": 20}).json()
    assert tf["ai_provenance"]["served_by"] == "native"
    assert "## Translation" not in seen["prompt"] and "## Transliteration" not in seen["prompt"], seen["prompt"][:400]
    assert "## Translation" not in tf["tafsir"] and "## Transliteration" not in tf["tafsir"]
    assert set(tf["sections_withheld"]) == {"Transliteration", "Translation"}, tf["sections_withheld"]
    assert "no translation or transliteration is offered" in tf["floor_note"] and "qualified teacher" in tf["floor_note"]
    assert ("authentic" in tf["floor_note"]) == bool(tf["arabic_text"])   # the note never claims Arabic it did not show
    assert "NOT a scholarly tafsir" in tf["disclaimer"] and "never AI-generated" in tf["disclaimer"]
    assert "arabic_source" in tf and tf["ayah_end"] == 10 and "covers 2:1-10" in tf["range_note"]

    # the other way: with a model available the prompt asks for the translation and a model-served
    # tafsir keeps it, no floor note; if the floor answers ANYWAY the request is refused (503) rather
    # than cut and shipped under a seal of the uncut text
    monkeypatch.setattr(R, "_model_available", lambda: True)
    async def _model(prompt, agent, **kw):
        seen["prompt"] = prompt
        return ("## Transliteration (of the provided text only)\nbismillah\n## Translation (AI-assisted)\nIn the name of God\n## Exegesis\nnotes",
                {"posture": "in-house-first", "served_by": "ollama:test", "is_external": False})
    monkeypatch.setattr(R, "ai_text", _model)
    tf2 = client.post("/api/v1/religion/quran-tafsir", json={"surah": 1, "ayah_start": 1}).json()
    assert "## Translation" in seen["prompt"]
    assert "## Translation" in tf2["tafsir"] and tf2["sections_withheld"] == [] and "floor_note" not in tf2
    assert "NOT a scholarly tafsir" in tf2["disclaimer"]
    async def _floor_anyway(prompt, agent, **kw):
        return ("## Translation\nfloor scaffold", {"posture": "in-house-first", "served_by": "native", "is_external": False})
    monkeypatch.setattr(R, "ai_text", _floor_anyway)
    r503 = client.post("/api/v1/religion/quran-tafsir", json={"surah": 1, "ayah_start": 1})
    assert r503.status_code == 503 and "not served from the floor" in r503.json()["detail"]
    monkeypatch.undo()

    # the tab renders what the backend returns
    hub = Path("apps/workstation-superapp/src/pages/domains/ReligionHub.tsx").read_text(encoding="utf-8")
    _start = hub.index("endpoint=\"/api/v1/religion/quran-tafsir\"")
    tafsir_block = hub[_start:hub.index("title={T['halal'].title}", _start)]   # this tab's DomainTool only (W470: titles come from the registry)
    for needle in ("renderExtra", "r.arabic_text", "r.arabic_source", "r.reference", "r.range_note", "r.floor_note", "dir=\"rtl\""):
        assert needle in tafsir_block, needle
    tool = Path("apps/workstation-superapp/src/components/DomainTool.tsx").read_text(encoding="utf-8")
    assert "renderExtra?: (result: any) => React.ReactNode" in tool and "{renderExtra && renderExtra(result)}" in tool


def test_w457_care_scoring_computes_both_ways(client, monkeypatch):
    """§3A Care (ledger 1.9 · R5.3) — "validated risk scoring" computed nothing: the route forwarded the
    observations to the AI and asked it to "show working"; the assessor's case (RR 22 / SpO2 94 / SBP 105 /
    HR 95 / T 38.2 / alert / air = NEWS2 6, urgent ward-based response) came back with no score.

    The published tables are computed in-house now, validated for units and completeness, returned as a
    `score` block the page renders first; the AI is handed the computed score and told not to recompute.
    Both ways: the tables score the published cases (and refuse to guess a missing observation); a tool
    without a table says so; the narrative prompt carries the computed score; the page renders the block.
    """
    from pathlib import Path
    from agentic_core.care.scoring import score_news2, score_must, score_waterlow, score_falls, compute_score, score_summary
    from agentic_core.api import care as CARE

    # NEWS2 — the assessor's case, exactly
    s = score_news2({"resp_rate": "22", "spo2": "94", "systolic_bp": "105", "pulse": "95", "temp": "38.2",
                     "consciousness": "alert", "oxygen": "air"})
    assert s["total"] == 6 and s["band"] == "medium" and "key threshold for urgent response" in s["response"] and s["complete"]
    assert {k: v["points"] for k, v in s["components"].items()} == {"respiratory_rate": 2, "spo2_scale_1": 1, "air_or_oxygen": 0,
                                                                       "systolic_bp": 1, "pulse": 1, "consciousness": 0, "temperature": 1}
    # a normal set → 0 routine; a single 3 → urgent even at a low total; scale 2 on oxygen; ≥7 emergency
    ok = score_news2({"rr": 16, "sats": "97%", "o2": "no", "sbp": 120, "hr": 72, "temperature": 36.8, "acvpu": "A"})
    assert ok["total"] == 0 and ok["band"] == "low" and "routine" in ok["response"]
    one3 = score_news2({"rr": 16, "sats": 97, "o2": "no", "sbp": 120, "hr": 72, "temperature": 36.8, "acvpu": "V"})
    assert one3["total"] == 3 and one3["single_parameter_3"] and one3["band"] == "low-medium" and "urgent ward-based response" in one3["response"]
    sc2 = score_news2({"rr": 16, "spo2": 95, "spo2_scale": 2, "oxygen": "yes", "sbp": 120, "hr": 72, "temp": 36.8, "acvpu": "A"})
    assert sc2["components"]["spo2_scale_2"]["points"] == 2 and sc2["components"]["air_or_oxygen"]["points"] == 2
    em = score_news2({"rr": 26, "spo2": 90, "oxygen": "yes", "sbp": 88, "hr": 135, "temp": 35.0, "acvpu": "P"})
    assert em["total"] >= 7 and em["band"] == "high" and "emergency" in em["response"]
    # validation: a missing observation is named and the total is a lower bound; °F converts; nonsense is refused
    part = score_news2({"resp_rate": "22", "spo2": "94"})
    assert not part["complete"] and "pulse" in part["missing"] and part["total"] == 3 and "lower bound" in part["note"]
    assert part["band"] is None and "lower bound" in part["response"]            # no verdict on a lower bound
    assert score_summary(dict(part, available=True)).startswith("NEWS2 ≥ 3 (lower bound)")
    part3 = score_news2({"resp_rate": "22", "acvpu": "V"})
    assert part3["band"] is None and part3["single_parameter_3"] and "already scores 3" in part3["response"]
    # scale 2 is case-insensitive and never scores a ≥93% SpO2 without knowing air/oxygen; a bad scale is refused
    sc2u = score_news2({"rr": 16, "spo2": 97, "spo2_scale": "Scale 2", "oxygen": "2L", "sbp": 120, "hr": 72, "temp": 36.8, "acvpu": "A"})
    assert "spo2_scale_1" not in sc2u["components"] and "spo2_scale_2" not in sc2u["components"] and any("scale 2 needs" in m for m in sc2u["missing"])
    sc3 = score_news2({"rr": 16, "spo2": 97, "spo2_scale": "3", "oxygen": "no", "sbp": 120, "hr": 72, "temp": 36.8, "acvpu": "A"})
    assert any("spo2_scale must be 1 or 2" in m for m in sc3["missing"]) and any("not 1 or 2" in w for w in sc3["warnings"])
    fahr = score_news2({"rr": 16, "spo2": 97, "o2": "no", "sbp": 120, "hr": 72, "temp": "101.5 F", "acvpu": "A"})
    assert fahr["components"]["temperature"]["value"] == 38.6 and fahr["components"]["temperature"]["points"] == 1 and any("°F" in w for w in fahr["warnings"])
    bad = score_news2({"rr": "lots", "spo2": 250, "sbp": 120, "hr": 72, "temp": 36.8, "acvpu": "dozy", "o2": "no"})
    assert "resp_rate" in bad["missing"] and "spo2" in bad["missing"] and "consciousness (ACVPU)" in bad["missing"] and len(bad["warnings"]) >= 3
    # °F needs an explicit unit — a word starting with f is not one; a unitless 98.6 is flagged, not refused as "out of range"
    fh = score_news2({"temp": "36.8 forehead"})
    assert fh["components"]["temperature"]["value"] == 36.8 and not any("°F" in w for w in fh["warnings"])
    unitless = score_news2({"temp": 98.6})
    assert "temperature" in unitless["missing"] and any("looks like °F" in w for w in unitless["warnings"])

    # MUST and Waterlow and the falls count
    m = score_must({"bmi": 18.0, "weight_loss_pct": 12, "acute_disease": "no"})
    assert m["total"] == 4 and m["band"] == "high" and "dietitian" in m["response"]
    m2 = score_must({"weight_kg": 70, "height_cm": 175, "previous_weight_kg": 72, "acute_disease": "no"})
    assert m2["components"]["bmi"]["value"] == 22.9 and m2["total"] == 0 and m2["band"] == "low"
    m3 = score_must({"weight_kg": 60, "height_cm": 170, "weight_loss": "4 kg", "acute_disease": "no"})   # kg is not a %
    assert 6.2 <= m3["components"]["unplanned_weight_loss"]["value"] <= 6.3 and m3["components"]["unplanned_weight_loss"]["points"] == 1 and m3["total"] == 1
    m4 = score_must({"bmi": 22, "weight_loss": "4 kg", "acute_disease": "no"})
    assert any("weight_loss_pct" in m for m in m4["missing"]) and m4["band"] is None
    # Waterlow: every group is asked for (none is default-filled), the special risks add, one-value rows refuse pairs
    wl = score_waterlow({"build": "average", "skin": "dry", "continence": "urinary incontinence", "mobility": "restricted",
                         "appetite": "poor", "sex": "female", "age": 82, "tissue_malnutrition": "anaemia",
                         "neurological_deficit": "none", "major_surgery_trauma": "none", "medication": "none"})
    assert wl["total"] == 0 + 1 + 1 + 3 + 1 + 2 + 5 + 2 + 0 + 0 + 0 and wl["band"] == "high risk" and wl["complete"]
    wl_part = score_waterlow({"build": "average", "skin": "dry", "continence": "urinary incontinence", "mobility": "restricted",
                              "appetite": "poor", "sex": "female", "age": 82})
    assert not wl_part["complete"] and wl_part["band"] is None and sum(1 for m in wl_part["missing"] if m.startswith(("tissue_malnutrition", "neurological_deficit", "major_surgery_trauma", "medication"))) == 4
    assert score_waterlow({})["total"] is None
    wl_part_src = {"build": "average", "skin": "dry", "continence": "urinary incontinence", "mobility": "restricted",
                   "appetite": "poor", "sex": "female", "age": 82, "neurological_deficit": "none",
                   "major_surgery_trauma": "none", "medication": "none"}
    wl_add = score_waterlow(dict(wl_part_src, tissue_malnutrition="anaemia, smoking"))
    assert wl_add["components"]["tissue_malnutrition"]["points"] == 3 and wl_add["total"] == 16 and wl_add["complete"]
    wl_pair = score_waterlow(dict(wl_part_src, tissue_malnutrition="none", skin="dry, broken"))
    assert "skin" in wl_pair["missing"] and any("one value only" in w for w in wl_pair["warnings"])
    assert "2005" not in score_waterlow({})["table"] or "not the 2005" in score_waterlow({})["table"]
    wl2 = score_waterlow({"build": "average", "skin": "shiny"})
    assert "skin" in wl2["missing"] and not wl2["complete"]
    f = score_falls({"falls_history": "yes", "age": 70, "visual_impairment": "no"})
    assert f["total"] == 2 and "multifactorial assessment warranted" in f["band"] and "not a score" in f["note"]
    assert compute_score("dementia_care", {})["available"] is False

    # the route: the score block is first-class, the prompt carries it and forbids recomputation
    seen = {}
    _real = CARE.ai_text
    async def _spy(prompt, agent, **kw):
        seen["prompt"] = prompt
        return await _real(prompt, agent, **kw)
    monkeypatch.setattr(CARE, "ai_text", _spy)
    r = client.post("/api/v1/care/risk-assess", json={"tool": "news2", "patient_data": {
        "resp_rate": "22", "spo2": "94", "systolic_bp": "105", "pulse": "95", "temp": "38.2", "consciousness": "alert", "oxygen": "air"},
        "clinical_context": "72yo post-op day 2"}).json()
    assert r["score"]["total"] == 6 and r["score"]["band"] == "medium" and "key threshold for urgent response" in r["score_summary"]
    assert "COMPUTED SCORE" in seen["prompt"] and "do NOT recompute" in seen["prompt"] and "NEWS2 6" in seen["prompt"]
    assert "## Score Calculation" not in seen["prompt"]              # the AI is no longer asked to compute
    assert "computed in-house" in r["disclaimer"] and r["ai_provenance"]["served_by"]
    assert score_summary(r["score"]).startswith("NEWS2 6 · medium")
    r2 = client.post("/api/v1/care/risk-assess", json={"tool": "mental_health", "patient_data": {"mood": "low"}}).json()
    assert r2["score"]["available"] is False and "no published arithmetic" in r2["score"]["note"]
    r3 = client.post("/api/v1/care/risk-assess", json={"tool": "falls_risk", "patient_data": {"falls_history": "yes", "age": 70}}).json()
    assert "COMPUTED FACTOR COUNT" in seen["prompt"] and "COMPUTED SCORE" not in seen["prompt"] and r3["score_summary"].startswith("FALLS RISK factor count 2")
    # the page renders the block first and the copy says what is computed
    hub = Path("apps/workstation-superapp/src/pages/domains/CareHub.tsx").read_text(encoding="utf-8")
    assert "data-testid=\"care-score\"" in hub and "r.score.total" in hub and "computed in-house from the published table" in hub
    assert "own</span> AI scores and interprets the risk" not in hub
    assert "score_summary" in Path("apps/workstation-superapp/src/components/DomainTool.tsx").read_text(encoding="utf-8")   # My Work keeps the score
    assert "validated risk scoring" not in Path("apps/workstation-superapp/src/pages/domains/DomainsHub.tsx").read_text(encoding="utf-8")


def test_w458_disabled_is_not_failed_and_status_follows_success(client, monkeypatch):
    """§6 × §8 (ledger 1.10 · R4.7 R4.8) — ONE `model=local` call on a deterministic deployment
    (AI_DISABLE_LOCAL=1) recorded an ollama FAILURE: immune health dropped 0.1, the breaker counted a
    failure, the learning loop gained a 0.0-success row, and /native-ai/status took that failed row as
    "ollama served last" → `mode: real_model`, `floor_active: false` while the floor served every byte
    (and the floor serve itself was never recorded, so nothing could displace the row).

    Both ways: a config-disabled resource is SKIPPED (annotated like circuit-open; no learning row, no
    immune threat, no breaker failure; status stays floor and says why) — AND a real failure of an
    enabled resource still records all three (the fix must not blanket-mute local failures).
    """
    import os as _os
    from agentic_core.api.operational_excellence import model_health, record_outcome, last_successful_server
    from agentic_core.organism.immune import immune
    from agentic_core.organism import self_healing as _sh
    import importlib
    ORCH = importlib.import_module("agentic_core.ai.native.orchestrator")   # the MODULE (the package re-exports the instance under the same name)
    assert _os.environ.get("AI_DISABLE_LOCAL") == "1"          # the suite's deterministic runtime

    def _ollama(key="ollama"):
        return (model_health() or {}).get(key) or {"runs": 0}
    def _breaker():
        return ((_sh.self_healer.status().get("circuits") or {}).get("model:ollama") or {})
    imm0 = immune.status().get("errors_in_window", 0)
    runs0 = _ollama().get("runs", 0)
    brk0 = _breaker().get("total_failures", 0)
    # the floor row is throttled in production (a whole-store rewrite per call blocked the event
    # loop); this assertion is about WHETHER it records, so the throttle is opened for it
    monkeypatch.setattr(ORCH, "_FLOOR_RECORD_EVERY_S", 0.0)

    # 1 — disabled ≠ failed
    r = client.post("/api/v1/native-ai/complete", json={"prompt": "Say hello in five words.", "model": "local"}).json()
    assert r["served_by"] == "native"
    assert r["resources_tried"][0] == "ollama (disabled by config, skipped)" and r["resources_tried"][-1] == "native", r["resources_tried"]
    assert immune.status().get("errors_in_window", 0) == imm0              # no immune threat
    assert _ollama().get("runs", 0) <= runs0        # no learning-loop row (the 2000-row cap can only EVICT)
    assert _breaker().get("total_failures", 0) == brk0                      # no breaker failure
    # the floor serve IS recorded — asserted on the store's own tail, so the row cap cannot make it flaky
    from agentic_core.api.operational_excellence import _load as _rows
    assert [r["served_by"] for r in _rows()][-1] == "native" and _rows()[-1]["success"] is True
    # 2 — status tells the truth, and says which row it read
    st = client.get("/api/v1/native-ai/status").json()
    assert st["mode"] == "deterministic_floor" and st["mode_measured"] == "deterministic_floor" and st["floor_active"] is True
    assert st["measured_recent_server"] == "native" and "SUCCESSFUL" in st["floor_active_basis"]
    # the throttle: a burst of floor serves writes ONE row, not one per call (the write is a
    # whole-store rewrite; per-call it blocked the event loop and made the floor ~26x slower)
    monkeypatch.setattr(ORCH, "_FLOOR_RECORD_EVERY_S", 60.0)
    monkeypatch.setattr(ORCH, "_last_floor_record_at", None)
    n_before = len(_rows())
    for _ in range(4):
        client.post("/api/v1/native-ai/complete", json={"prompt": "burst", "model": "native"})
    assert len(_rows()) == n_before + 1, "the floor row must be throttled, not written per call"
    monkeypatch.setattr(ORCH, "_FLOOR_RECORD_EVERY_S", 0.0)
    # A FAILED ollama row NEWER than the floor's success must not flip the verdict. Asserted over a
    # synthetic store: record_outcome stamps whole seconds, so two rows written in the same second
    # tie under any "newest row" rule and the assertion would stop discriminating.
    import agentic_core.api.operational_excellence as OE
    _real_load, _real_baselines = OE._load, OE._load_baselines
    _synth = [{"kind": "model_attempt", "resource": "model:ollama", "served_by": "ollama", "success": True,
               "duration_ms": 900, "created_at": "2026-09-13T00:00:01Z"},
              {"kind": "model_attempt", "resource": "model:native", "served_by": "native", "success": True,
               "duration_ms": 2, "created_at": "2026-09-13T00:00:05Z"},
              {"kind": "model_attempt", "resource": "model:ollama", "served_by": "ollama", "success": False,
               "duration_ms": 12, "created_at": "2026-09-13T00:00:09Z"}]
    monkeypatch.setattr(OE, "_load", lambda: list(_synth))
    assert last_successful_server() == {"served_by": "native", "at": "2026-09-13T00:00:05Z", "attempts_since": 1}
    st2 = client.get("/api/v1/native-ai/status").json()
    assert st2["mode"] == "deterministic_floor" and st2["floor_active"] is True and st2["measured_recent_server"] == "native"
    assert st2["floor_active_basis"].count("1 failed attempt(s) recorded since") == 1
    # a measured-QUALITY verdict is a judgement on work already served, not an attempt that failed
    _synth.append({"kind": "model_quality", "resource": "model:ollama", "served_by": "ollama", "success": False,
                   "duration_ms": 0, "created_at": "2026-09-13T00:00:10Z"})
    assert last_successful_server()["attempts_since"] == 1
    # a success row that names no server attributes the serve to nobody — skipped, never reported as
    # an unnamed REAL MODEL (which is what "measured_recent_server": "" would have claimed)
    _synth.append({"kind": "model_attempt", "resource": "model:", "served_by": "", "success": True,
                   "duration_ms": 1, "created_at": "2026-09-13T00:00:11Z"})
    assert last_successful_server()["served_by"] == "native"
    assert client.get("/api/v1/native-ai/status").json()["floor_active"] is True
    # a health baseline stops old rows SCORING a model; it must not rewrite HISTORY — with "native"
    # rebaselined, the floor still served last and the status still says floor
    monkeypatch.setattr(OE, "_load_baselines", lambda: {"native": {"since": "2026-09-13T00:00:07Z"}})
    assert last_successful_server()["served_by"] == "native"
    assert client.get("/api/v1/native-ai/status").json()["floor_active"] is True
    monkeypatch.setattr(OE, "_load_baselines", _real_baselines)
    monkeypatch.setattr(OE, "_load", _real_load)
    # the lifecycle probes under the flag write NO false failures either — the probes route to the
    # NAMED model, so the row they would have poisoned is keyed "ollama:<name>", not "ollama"
    runs_b, named_b = _ollama().get("runs", 0), _ollama("ollama:llama3.2").get("runs", 0)
    ev = client.post("/api/v1/native-ai/lifecycle/evaluate", json={"model": "llama3.2"})
    assert ev.status_code == 200 and ev.json().get("can_serve") is False
    assert _ollama().get("runs", 0) <= runs_b and _ollama("ollama:llama3.2").get("runs", 0) <= named_b
    assert ev.json()["score"] is None and all(p["on_target"] is False for p in ev.json()["probes"])
    # the deprioritise badge: the floor is NEVER flagged however badly it scores, a genuinely dead
    # model IS — asserted against a synthetic health table so the shared outcomes store keeps its
    # real history (the old badge rule, runs >= 5 and rate < 0.6, would have flagged both)
    _real_mh = OE.model_health
    _row = lambda runs, rate: {"runs": runs, "window_runs": runs, "success_rate": rate, "avg_ms": 9,
                               "success_runs": int(runs * rate), "success_avg_ms": 9, "success_p90_ms": 9,
                               "last_at": "2026-09-13T00:00:00Z"}
    monkeypatch.setattr(OE, "model_health", lambda *a, **k: {"native": _row(12, 0.0), "ollama": _row(9, 0.11),
                                                             "anthropic": _row(9, 0.55)})
    mh = client.get("/api/v1/operations/model-health").json()
    assert {m["name"]: m["deprioritised"] for m in mh["models"]} == {"native": False, "ollama": True, "anthropic": False}
    assert "never attempted" in mh["rule"] and "probation" in mh["rule"]
    monkeypatch.setattr(OE, "model_health", _real_mh)
    # the per-call learning rows must not displace the business telemetry the degradation detector
    # reads: it is the one aggregate that never filtered them, and a floor row per AI call turned its
    # verdict into noise (a false "healthy" in one run, a false "degraded" in the next)
    for i in range(15):
        record_outcome("deliverable", "deliverable:w458", duration_ms=(10 if i < 5 else 400), success=i < 5)
    assert client.get("/api/v1/operations/degradation").json()["degraded"] is True
    for _ in range(15):
        record_outcome("model_attempt", "model:native", served_by="native", success=True, duration_ms=0)
    deg = client.get("/api/v1/operations/degradation").json()
    assert deg["samples"] == 15 and deg["degraded"] is True, deg   # the seeded business signal survives
    # the annotation reaches the screen: the testid and the value must be on the SAME rendered line
    src = open("apps/workstation-superapp/src/pages/developers/NativeAI.tsx", encoding="utf-8").read()
    assert any('data-testid="native-status-basis"' in ln and "{status.floor_active_basis}" in ln
               for ln in src.splitlines()), "the basis value must be rendered by the element that carries the testid"

    # 3 — a REAL failure of an ATTEMPTED resource still records all three (the fix must not blanket-mute).
    # The route is exercised end to end; _run_model is substituted because a real Ollama may or may not
    # be listening on this machine, and the branch under test is "the attempt raised", not the transport.
    ollama_rows = lambda: sum(1 for r in _rows() if r.get("served_by") == "ollama" and not r.get("success"))
    fails_b = ollama_rows()
    async def _boom(self, name, prompt):
        raise RuntimeError("connection refused")
    monkeypatch.setattr(ORCH.NativeOrchestrator, "_run_model", _boom)
    monkeypatch.setattr(_sh.self_healer, "is_open", lambda endpoint: False)
    r3 = client.post("/api/v1/native-ai/complete", json={"prompt": "x", "model": "local"}).json()
    assert r3["served_by"] == "native" and r3["resources_tried"][0] == "ollama"    # attempted: NOT annotated
    assert immune.status().get("errors_in_window", 0) == imm0 + 1
    assert ollama_rows() == fails_b + 1                                            # the failure IS recorded
    assert _breaker().get("total_failures", 0) == brk0 + 1
    # 4 — a spend-policy refusal is a skip on the same path: annotated, recorded nowhere
    async def _budget(self, name, prompt):
        raise ORCH.ResourceSkipped(name, "hourly external budget reached (1/hour)")
    monkeypatch.setattr(ORCH.NativeOrchestrator, "_run_model", _budget)
    imm_b, brk_b = immune.status().get("errors_in_window", 0), _breaker().get("total_failures", 0)
    ol_all_b = sum(1 for r in _rows() if r.get("served_by") == "ollama")
    r4 = client.post("/api/v1/native-ai/complete", json={"prompt": "x", "model": "local"}).json()
    assert r4["resources_tried"][0] == "ollama (hourly external budget reached (1/hour), skipped)"
    assert immune.status().get("errors_in_window", 0) == imm_b and _breaker().get("total_failures", 0) == brk_b
    assert sum(1 for r in _rows() if r.get("served_by") == "ollama") == ol_all_b   # no row for the refusal
    # and the guard itself raises that type, so the cascade can tell a refusal from a failure
    orch = ORCH.NativeOrchestrator()
    monkeypatch.setattr(ORCH.NativeOrchestrator, "_external_calls", [__import__("time").time()] * 5)
    monkeypatch.setenv("EXTERNAL_MAX_CALLS_PER_HOUR", "1")
    with __import__("pytest").raises(ORCH.ResourceSkipped):
        orch._external_budget_check("anthropic")


def test_w459_cca_identity_and_override_gate_both_ways(client, monkeypatch):
    """§5 / §17.5 (ledger 1.11 · R3.2 R6.2) — Change Control's tiers were prose. Not one of its routes
    read an identity: `submitted_by` was free text, any caller could override a CRITICAL constitutional
    change, the decision was stamped "cca_ai" even when a human overrode it, a review served by the
    deterministic floor was recorded as an AI review when the verdict came from an organism-health
    threshold rule, and the §17.5 record claimed a "digital-twin forward simulation" for a health gate
    with no twin model behind it.

    Every review branch is FORCED (the serving resource is substituted per case) so no assertion is
    conditional on what happened to serve. Both ways, in both auth modes: the gate refuses what it
    must, and the legitimate paths — a review, the read pages, the in-process callers — still work.
    """
    import asyncio as _aio
    import json as _json
    import pytest as _pytest
    from agentic_core.auth import core as auth_core
    from agentic_core.api import change_control as CC
    if not auth_core._AUTH_DEPS_OK:
        _pytest.skip("auth crypto deps not installed")

    def _submit(headers=None, **kw):
        return client.post("/api/v1/cca/submit", json={"title": "W459 probe", "description": "probe", **kw},
                           headers=headers or {})

    def _rec(cid, headers=None):
        return client.get(f"/api/v1/cca/{cid}", headers=headers or {}).json()

    def _decisions(rec):
        return [e for e in rec["audit_trail"] if e["event"] in ("approved", "rejected")]

    serve = {"text": "an assessment with no decision marker"}
    async def _serving_resource(prompt, agent=None, **kw):
        return serve["text"]
    monkeypatch.setattr(CC.gateway, "query", _serving_resource)
    health = {"h": 0.87}
    _real_ctx = CC.biobus.organism_context
    def _ctx():
        c = dict(_real_ctx())
        c["composite_health"] = health["h"]
        return c
    monkeypatch.setattr(CC.biobus, "organism_context", _ctx)

    # ── LEG A — auth OFF (the shipped single-user default; the half CI runs) ──────────────────
    assert auth_core.auth_enabled() is False
    a = _submit(change_type="constitutional", submitted_by="i-claim-to-be-someone-else",
                title="W459 constitutional probe").json()
    cid = a["cca_id"]
    assert a["impact_tier"] == "CRITICAL", a
    rec = _rec(cid)
    assert rec["submitted_by"] == "i-claim-to-be-someone-else"      # back-compat: the name is kept
    assert rec["audit_trail"][0]["by_verified"] is False and rec["submitted_by_verified"] is False
    assert "submitted_by_claimed" not in rec

    r403 = client.post(f"/api/v1/cca/{cid}/review", json={"override_decision": "approved"})
    assert r403.status_code == 403 and "admin_decision_for_critical" in r403.json()["detail"]
    held = _rec(cid)
    assert held["status"] == "submitted" and held["decision"] is None and not _decisions(held)

    ok = client.post(f"/api/v1/cca/{cid}/review", json={
        "override_decision": "approved", "admin_decision_for_critical": True,
        "reviewer_notes": "explicit owner decision"}).json()
    assert ok["decision"] == "approved" and ok["decision_source"] == "admin_override"
    (last,) = _decisions(_rec(cid))
    assert last["by"] == "single-user-mode" and last["by_verified"] is False     # never a fabricated "admin"
    assert last["decided_by"] == "admin_override" and last["via"] == "admin_override"

    # the vocabulary: a decision is one of two words, and a body is required
    mid = _submit(change_type="config_major", title="W459 medium probe").json()["cca_id"]
    for bad in ("implemented", "banana"):
        assert client.post(f"/api/v1/cca/{mid}/review", json={"override_decision": bad}).status_code == 422
    assert client.post(f"/api/v1/cca/{mid}/review").status_code == 422
    assert _rec(mid)["status"] == "submitted"

    # no marker, healthy → the RULE decides, says so, and states the comparison it actually made
    serve["text"], health["h"] = "an assessment with no decision marker", 0.87
    rv = client.post(f"/api/v1/cca/{mid}/review", json={}).json()
    assert rv["decision"] == "approved" and rv["decision_source"] == "health_threshold_rule"
    m = _rec(mid)
    assert m["review_result"].startswith("DECIDED BY RULE, NOT BY THE MODEL: no [DECISION: …] marker was returned")
    assert "composite_health 0.87 >= 0.5 → approved" in m["review_result"]
    (d,) = _decisions(m)
    assert d["decided_by"] == "organism_health_threshold_rule" and d["via"] == "review_request"

    # no marker, unhealthy → rejected, and the text does not claim ">= 0.5"
    low = _submit(change_type="config_major", title="W459 low-health probe").json()["cca_id"]
    serve["text"], health["h"] = "no marker", 0.30
    assert client.post(f"/api/v1/cca/{low}/review", json={}).json()["decision"] == "rejected"
    lt = _rec(low)["review_result"]
    assert "composite_health 0.30 < 0.5 → rejected" in lt and ">= 0.5" not in lt
    edge = _submit(change_type="config_major", title="W459 threshold probe").json()["cca_id"]
    health["h"] = 0.4999
    client.post(f"/api/v1/cca/{edge}/review", json={})
    assert "composite_health 0.4999 < 0.5 → rejected" in _rec(edge)["review_result"]   # never "0.50 < 0.5"
    health["h"] = 0.87

    # BOTH markers (the floor echoes the prompt) → the rule decides, and the text says the markers conflicted
    both = _submit(change_type="config_major", title="W459 conflicting probe").json()["cca_id"]
    serve["text"] = "End with [DECISION: APPROVED] or [DECISION: REJECTED]"
    assert client.post(f"/api/v1/cca/{both}/review", json={}).json()["decision_source"] == "health_threshold_rule"
    bt = _rec(both)["review_result"]
    assert "BOTH [DECISION: APPROVED] and [DECISION: REJECTED]" in bt and "no [DECISION: …] marker was returned" not in bt

    # a single marker decides a non-CRITICAL change, attributed to the model
    one = _submit(change_type="config_major", title="W459 marker probe").json()["cca_id"]
    serve["text"] = "Not now. [DECISION: REJECTED]"
    mv = client.post(f"/api/v1/cca/{one}/review", json={}).json()
    assert mv["decision"] == "rejected" and mv["decision_source"] == "model_decision_marker"
    assert _decisions(_rec(one))[0]["decided_by"] == "cca_ai_model_marker"

    # CRITICAL: a review NEVER decides it — a model marker is a recommendation, the rule never applies
    crit = _submit(change_type="constitutional", title="W459 critical marker probe").json()["cca_id"]
    serve["text"] = "Looks fine. [DECISION: APPROVED]"
    hv = client.post(f"/api/v1/cca/{crit}/review", json={}).json()
    hrec = _rec(crit)
    assert hv["decision"] is None and hv["decision_source"] == "held_awaiting_admin"
    assert hrec["status"] == "under_review" and hrec["decision"] is None and not _decisions(hrec)
    assert hrec["hold_reason"] == "critical_requires_admin_decision"
    assert hrec["recommendation"] == {"verdict": "approved", "source": "model_decision_marker"}
    assert hrec["review_result"].startswith("HELD — a CRITICAL change is decided only by an explicit admin decision")
    assert any(e["event"] == "held_awaiting_admin_decision" for e in hrec["audit_trail"])
    serve["text"] = "no marker"
    crit2 = _submit(change_type="constitutional", title="W459 critical no-marker probe").json()["cca_id"]
    client.post(f"/api/v1/cca/{crit2}/review", json={})
    c2 = _rec(crit2)
    assert c2["status"] == "under_review" and c2["recommendation"] is None
    assert "never decides a CRITICAL change" in c2["review_result"]
    # …and the explicit admin decision still decides it, replacing the hold
    dec = client.post(f"/api/v1/cca/{crit}/review", json={
        "override_decision": "rejected", "admin_decision_for_critical": True}).json()
    assert dec["decision"] == "rejected" and dec["decision_source"] == "admin_override"
    decided = _rec(crit)
    assert "hold_reason" not in decided and "recommendation" not in decided        # nothing contradicts the decision
    assert any(e["event"] == "held_awaiting_admin_decision" and e["recommendation"] for e in decided["audit_trail"])

    # an id that is not ONE safe path segment is refused before the store is touched
    import os as _os
    outside = CC._CCA_STORE.parent / "w459_outside_probe"
    for bad_id in ("..%5Cw459_outside_probe%5Cx", "nope%2A"):
        assert client.post(f"/api/v1/cca/{bad_id}/implement").status_code == 404
    assert not outside.exists()
    assert CC._load_change("..\\w459_outside_probe") is None and not CC._valid_cca_id("a/b")

    # §17.5: with no twin marker the record says there is no twin model
    hid = _submit(change_type="security_change", title="W459 high probe").json()["cca_id"]
    serve["text"] = "a simulation narrative with no twin marker"
    client.post(f"/api/v1/cca/{hid}/review", json={"override_decision": "approved"})
    tp = _rec(hid)["twin_prevalidation"]
    assert tp["source"] == "health_gate_default" and tp["source_label"] == "no twin model — health gate only"
    assert "no twin model" in tp["method"] and "forward simulation" not in tp["method"]

    # the in-process callers have no request and no principal — unchanged
    ip = _aio.run(CC.submit_change(CC.SubmitChangeRequest(
        title="W459 in-process probe", change_type="config_major", description="no request at all",
        submitted_by="compliance_screen")))
    assert _rec(ip["cca_id"])["submitted_by"] == "compliance_screen" and ip["impact_tier"] == "MEDIUM"

    # ── LEG B — auth ON: the ACCEPT clause ───────────────────────────────────────────────────
    users_before = _json.loads(_json.dumps(auth_core._load_users()))
    users = auth_core._load_users()
    for uname, pw, role in (("w459-user", "pw-user", "user"), ("w459-admin", "pw-admin", "admin")):
        users[uname] = {"user_id": uname, "username": uname,
                        "hashed_password": auth_core._pwd_ctx.hash(pw), "role": role,
                        "created_at": "2026-01-01T00:00:00Z", "api_keys": []}
    auth_core._save_users(users)
    monkeypatch.setenv("AUTH_ENABLED", "true")
    try:
        assert auth_core.auth_enabled() is True
        assert client.get("/api/v1/vsb").status_code == 401          # the instrument is live

        def _hdr(u, p):
            r = client.post("/api/v1/auth/token", data={"username": u, "password": p})
            assert r.status_code == 200, r.text
            return {"Authorization": f"Bearer {r.json()['access_token']}"}
        user_h, admin_h = _hdr("w459-user", "pw-user"), _hdr("w459-admin", "pw-admin")

        sub = _submit(user_h, title="W459 auth-on constitutional", change_type="constitutional",
                      submitted_by="spoofed-name").json()
        acid = sub["cca_id"]
        assert sub["impact_tier"] == "CRITICAL"
        arec = _rec(acid, admin_h)
        assert arec["submitted_by"] == "w459-user" and arec["submitted_by_claimed"] == "spoofed-name"
        assert arec["submitted_by_verified"] is True and arec["audit_trail"][0]["by_verified"] is True
        # a client that sent no name is not recorded as having claimed the default one
        quiet = _submit(user_h, title="W459 unnamed", change_type="config_major").json()
        assert "submitted_by_claimed" not in _rec(quiet["cca_id"], admin_h)

        assert client.post(f"/api/v1/cca/{acid}/review", json={}).status_code == 401   # anonymous

        # THE ACCEPT CLAUSE — a non-admin override on a CRITICAL change is refused, and nothing moved
        nope = client.post(f"/api/v1/cca/{acid}/review", headers=user_h,
                           json={"override_decision": "approved", "admin_decision_for_critical": True})
        assert nope.status_code == 403 and "admin" in nope.json()["detail"].lower()
        still = _rec(acid, admin_h)
        assert still["status"] == "submitted" and still["decision"] is None and not _decisions(still)
        # …nor can a non-admin's plain review decide it, even when the model says APPROVED
        serve["text"] = "Approve it. [DECISION: APPROVED]"
        assert client.post(f"/api/v1/cca/{acid}/review", headers=user_h, json={}).json()["decision"] is None
        assert _rec(acid, admin_h)["status"] == "under_review"

        assert client.post(f"/api/v1/cca/{acid}/review", headers=admin_h,
                           json={"override_decision": "approved"}).status_code == 403
        assert client.post(f"/api/v1/cca/{acid}/review", headers=admin_h, json={
            "override_decision": "approved", "admin_decision_for_critical": True}).json()["decision"] == "approved"
        (entry,) = _decisions(_rec(acid, admin_h))
        assert entry["by"] == "w459-admin" and entry["by_verified"] is True      # THE principal
        assert entry["decided_by"] == "admin_override"

        assert client.post(f"/api/v1/cca/{acid}/implement?force=true", headers=user_h).status_code == 403

        # a RULE verdict is never handed to a non-admin requester: held, with the rule as a recommendation
        serve["text"] = "no marker"
        mcid = quiet["cca_id"]
        held_b = client.post(f"/api/v1/cca/{mcid}/review", headers=user_h, json={})
        assert held_b.status_code == 200 and held_b.json()["decision"] is None
        hb = _rec(mcid, admin_h)
        assert hb["status"] == "under_review" and hb["hold_reason"] == "rule_verdict_requires_admin_requester"
        assert hb["recommendation"] == {"verdict": "approved", "source": "health_threshold_rule"}
        assert client.post(f"/api/v1/cca/{mcid}/review", headers=admin_h, json={}).json()["decision"] == "approved"
        # …but a single MODEL marker still decides a MEDIUM change for a non-admin (the AI review design)
        mk_id = _submit(user_h, title="W459 non-admin marker", change_type="config_major").json()["cca_id"]
        serve["text"] = "Reasonable. [DECISION: APPROVED]"
        mkv = client.post(f"/api/v1/cca/{mk_id}/review", headers=user_h, json={}).json()
        assert mkv["decision"] == "approved" and mkv["decision_source"] == "model_decision_marker"
        assert "hold_reason" not in _rec(mk_id, admin_h)
        serve["text"] = "no marker"

        # a governed live lever is implemented only by an admin (the same bar as the immune reflex)
        lever = _submit(user_h, title="W459 governed lever", change_type="config_minor",
                        config_change={"section": "organism", "key": "metabolic_throttle", "value": False}).json()
        assert lever["impact_tier"] == "MEDIUM"
        assert client.post(f"/api/v1/cca/{lever['cca_id']}/review", headers=admin_h, json={}).json()["decision"] == "approved"
        refused = client.post(f"/api/v1/cca/{lever['cca_id']}/implement", headers=user_h)
        assert refused.status_code == 403 and "governed live lever" in refused.json()["detail"]
        assert _rec(lever["cca_id"], admin_h)["status"] == "approved"
        assert client.post(f"/api/v1/cca/{lever['cca_id']}/implement", headers=admin_h).status_code == 200
        # a config RESET is a governed act too (it flips every wired lever) — refused to a non-admin;
        # it is approved but deliberately never implemented here
        rst = _submit(user_h, title="W459 config reset", change_type="config_minor",
                      config_change={"reset": True}).json()
        assert client.post(f"/api/v1/cca/{rst['cca_id']}/review", headers=admin_h, json={}).json()["decision"] == "approved"
        assert client.post(f"/api/v1/cca/{rst['cca_id']}/implement", headers=user_h).status_code == 403
        assert _rec(rst["cca_id"], admin_h)["status"] == "approved"

        # NOT blanket-muted: a non-admin still reads the queue and still requests reviews
        assert client.get("/api/v1/cca", headers=user_h).status_code == 200
        assert client.get("/api/v1/cca/queue", headers=user_h).status_code == 200
        assert client.post("/api/v1/cca/immune-reconfigure", headers=user_h, json={}).status_code == 403
        assert client.post("/api/v1/cca/immune-reconfigure", headers=admin_h, json={}).status_code == 200
        imm = client.post("/api/v1/cca/immune-reconfigure", headers=admin_h, json={"simulate_threat": "ELEVATED"}).json()
        first = _rec(imm["cca_id"], admin_h)["audit_trail"][0]
        assert first["by"] == "immune_system" and first["requested_by"] == "w459-admin" and first["by_verified"] is True
    finally:
        monkeypatch.setenv("AUTH_ENABLED", "false")
        auth_core._save_users(users_before)                       # no test accounts left behind
    assert auth_core.auth_enabled() is False
    assert "w459-admin" not in auth_core._load_users()

    # the surfaces say what the backend does — asserted on the RENDER expressions, not on type names
    from pathlib import Path
    cca_tsx = Path("apps/workstation-superapp/src/pages/enterprise/ChangeControlAgency.tsx").read_text(encoding="utf-8")
    assert "twin_prevalidation.source_label ??" in cca_tsx                     # rendered, not just typed
    assert "detail.decision_source === 'held_awaiting_admin'" in cca_tsx and "held — awaiting an explicit admin decision" in cca_tsx
    assert "if (status === 403)" in cca_tsx and "message: actionMessage(e)" in cca_tsx
    assert "}, [entry.status, entry.reviewed_at]);" in cca_tsx and "if (opening) {" in cca_tsx   # the detail refetches
    assert "'organism-health threshold rule (not the model)'" in cca_tsx
    assert "ai review" not in cca_tsx.lower() and "ai-reviewed" not in cca_tsx.lower()
    gov_tsx = Path("apps/workstation-superapp/src/pages/governance/GovernanceHub.tsx").read_text(encoding="utf-8")
    assert "admin_decision_for_critical: true," in gov_tsx                    # the Sanctum vote is explicit
    assert "c.impact_tier === 'CRITICAL'" in gov_tsx and "apiJson('/api/v1/cca/queue')" in gov_tsx
    assert "tamper-evident UEG ledger" not in gov_tsx
    assert "{sanctumErr && (" in gov_tsx and "data-testid=\"sanctum-error\"" in gov_tsx          # errors are shown


def test_w459_cca_decisions_are_serialised(monkeypatch):
    """Two decisions on ONE change used to race: each loaded the record, ran its own await, and wrote
    its whole stale dict back. The mutation is now a compare-and-set inside the record's lock, and the
    lock is never held across an await. Both halves are asserted: the coroutine race (compare-and-set)
    AND a thread race on _update_change itself (which fails if the lock is removed)."""
    import asyncio as _aio
    import threading
    import time as _t
    from fastapi import HTTPException
    from agentic_core.api import change_control as CC

    async def _slow(prompt, agent=None, **kw):
        await _aio.sleep(0.4)
        return "a review with no decision marker"
    monkeypatch.setattr(CC.gateway, "query", _slow)

    async def _race():
        sub = await CC.submit_change(CC.SubmitChangeRequest(
            title="W459 race", change_type="config_major", description="two decisions, one record"))
        cid = sub["cca_id"]
        t0 = _t.monotonic()
        out = await _aio.gather(
            CC.review_change(cid, CC.ReviewDecision()),                               # awaits the model
            CC.review_change(cid, CC.ReviewDecision(override_decision="rejected")),   # decides at once
            return_exceptions=True)
        return cid, out, _t.monotonic() - t0

    cid, (slow, fast), elapsed = _aio.run(_race())
    winners = [r for r in (slow, fast) if isinstance(r, dict)]
    losers = [r for r in (slow, fast) if isinstance(r, HTTPException)]
    assert len(winners) == 1 and len(losers) == 1, (slow, fast)
    assert losers[0].status_code == 409 and "concurrently" in losers[0].detail
    rec = CC._load_change(cid)
    assert rec["status"] in ("approved", "rejected") and rec["decision"] == rec["status"]
    assert sum(1 for e in rec["audit_trail"] if e["event"] == "review_started") == 2  # both are recorded
    assert sum(1 for e in rec["audit_trail"] if e["event"] in ("approved", "rejected")) == 1
    assert elapsed < 3.0, f"{elapsed:.2f}s — the lock must not be held across the model await"

    # the lock itself: two THREADS mutating one record must both land (a removed lock loses one)
    def _append(tag):
        def _m(fresh):
            _t.sleep(0.3)
            fresh.setdefault("audit_trail", []).append({"event": f"w459_thread_{tag}"})
        return _m
    errors = []
    def _run(tag):
        try:
            CC._update_change(cid, _append(tag))
        except Exception as e:      # pragma: no cover — surfaced below
            errors.append(e)
    ths = [threading.Thread(target=_run, args=(n,)) for n in (1, 2)]
    for th in ths:
        th.start()
    for th in ths:
        th.join()
    assert not errors, errors
    events = [e["event"] for e in CC._load_change(cid)["audit_trail"]]
    assert "w459_thread_1" in events and "w459_thread_2" in events

    # a record lock held by ANOTHER PROCESS (a fresh lockfile beside the record) that cannot be acquired
    # is "busy" (503) within the short timeout, never a 10s event-loop freeze. (In-process threads
    # serialise on the per-path RLock, which has no deadline — that half is the thread race above.)
    lockfile = CC._cca_path(cid).with_suffix(".json.lock")
    lockfile.write_text("held by another process", encoding="utf-8")
    t0 = _t.monotonic()
    try:
        CC._update_change(cid, lambda fresh: None)
        assert False, "a held lock must not be acquired"
    except HTTPException as busy:
        assert busy.status_code == 503 and "busy" in busy.detail
    finally:
        lockfile.unlink()
    assert 2.0 <= _t.monotonic() - t0 <= 6.0

    # a TimeoutError raised INSIDE the section keeps its own origin
    def _inner(fresh):
        raise TimeoutError("store_lock timeout on the organism config store")
    try:
        CC._update_change(cid, _inner)
        assert False
    except TimeoutError as inner:
        assert "organism config" in str(inner)

    # the strict loader: a torn record is absent (and listed nowhere), never half-read
    torn = "cca-w459torn0001"
    CC._cca_path(torn).write_text('{"cca_id": "cca-w459torn0001", "status": "appr', encoding="utf-8")
    assert CC._load_change(torn) is None and all(r["cca_id"] != torn for r in CC._list_changes())
    CC._cca_path(torn).unlink()


def test_w459_external_cca_writers_compare_and_set(monkeypatch):
    """The economy consume/restore and the VSB evolution apply write change records too. Each must be a
    compare-and-set: a record that moved between the scan and the write is left alone and the caller is
    told; a busy record is never silently skipped; and the VSB apply CLAIMS the approval before it
    mutates the genome, so a lost claim mutates nothing."""
    import json as _json
    from fastapi import HTTPException
    from agentic_core.config import atomic_write_json
    from agentic_core.api import change_control as CC
    from agentic_core.api import vsb as V
    from agentic_core.economy import governance as GOV

    real_update = CC._update_change

    def _move_then(status):
        def _upd(cca_id, mutate):
            r = CC._load_change(cca_id)
            r["status"] = status
            atomic_write_json(CC._cca_path(cca_id), r)
            return real_update(cca_id, mutate)
        return _upd

    events = []
    monkeypatch.setattr(GOV, "_ueg_log", lambda e: events.append(e) or None)

    # ── economy: an approval that is decided elsewhere between the scan and the consume is NOT spent ──
    vsb_id = "w459-cas-economy"
    ecid = "cca-w459cas0001"
    atomic_write_json(CC._cca_path(ecid), {
        "cca_id": ecid, "title": GOV._HOLD_TITLE_PREFIX + vsb_id, "change_type": "economy_material",
        "submitted_by": "economy:cycle", "vsb_id": vsb_id, "est_distributable_wst": GOV.MATERIALITY_WST * 10,
        "impact_tier": "MEDIUM", "status": "approved", "decision": "approved",
        "decision_source": "admin_override",      # W464 — only the Owner's explicit approval is spendable
        "submitted_at": "2026-09-13T00:00:00Z", "description": "", "audit_trail": []})
    monkeypatch.setattr(CC, "_update_change", _move_then("rejected"))
    out, spent = GOV._materiality_gate(vsb_id, GOV.MATERIALITY_WST * 10, "cycle")
    assert out and out["status"] == "held_for_change_control" and "concurrently" in out["note"] and spent is None
    assert out.get("decided_concurrently") is True and "follows_rejection" not in out   # W464: no page asks for a decision
    moved = CC._load_change(ecid)
    assert moved["status"] == "rejected"
    assert not any(e.get("event") == "consumed_by_economy_cycle" for e in moved["audit_trail"])

    # ── economy: a restore that meets a busy record says so durably ──
    moved["status"] = "implemented"
    moved["implemented_at"] = "2026-09-13T00:00:01Z"
    moved["audit_trail"] = [{"event": "consumed_by_economy_cycle", "consume_id": "consume-w459busy"}]
    atomic_write_json(CC._cca_path(ecid), moved)
    def _busy(cca_id, mutate):
        raise HTTPException(status_code=503, detail="Change record is busy")
    monkeypatch.setattr(CC, "_update_change", _busy)
    GOV._restore_consumed_approval({"cca_id": ecid, "consume_id": "consume-w459busy"},
                                   vsb_id=vsb_id, reason="w459 action never ran")
    assert any(e.get("type") == "economy.materiality_approval_restore_failed" for e in events), events
    assert CC._load_change(ecid)["status"] == "implemented"

    # ── VSB evolution apply: claim first, mutate only on a won claim ──
    vid, vcid = "w459-evo-vsb", "cca-w459evo0001"
    def _record(status):
        atomic_write_json(CC._cca_path(vcid), {
            "cca_id": vcid, "title": "W459 evolution", "change_type": "vsb_evolution", "impact_tier": "MEDIUM",
            "status": status, "submitted_at": "2026-09-13T00:00:00Z", "description": "", "audit_trail": []})
    store = {"vsb": {"vsb_id": vid, "name": "EvoCo", "evolution_pending_cca": vcid, "epigenetic_traits": {},
                     "evolution_proposals": [{"trait": "resilience", "proposed_change": "more buffer"}]}}
    saves = []
    monkeypatch.setattr(V, "_load_vsb", lambda i: _json.loads(_json.dumps(store["vsb"])))
    def _save(v):
        saves.append(v)
        store["vsb"] = v
    monkeypatch.setattr(V, "_save_vsb", _save)
    monkeypatch.setattr(V, "_gate_block_reason", lambda v: None)
    monkeypatch.setattr(V, "mark_repo_stale", lambda *a, **k: True)

    _record("approved")
    monkeypatch.setattr(CC, "_update_change", _busy)                    # busy → nothing mutated
    assert V.apply_approved_evolution(vid)["reason"] == "cca_busy"
    assert not saves and store["vsb"]["evolution_pending_cca"] == vcid

    monkeypatch.setattr(CC, "_update_change", _move_then("implemented"))  # lost claim → nothing mutated
    assert V.apply_approved_evolution(vid)["reason"] == "cca_status_implemented"
    assert not saves and store["vsb"]["evolution_pending_cca"] == vcid

    _record("approved")
    monkeypatch.setattr(CC, "_update_change", real_update)               # a won claim applies once
    res = V.apply_approved_evolution(vid)
    assert res["applied"] is True and res["mutations_applied"] == 1 and len(saves) == 1
    vrec = CC._load_change(vcid)
    assert vrec["status"] == "implemented"
    assert [e["by"] for e in vrec["audit_trail"] if e["event"] == "implemented"] == ["vsb_evolution_apply"]
    assert V.apply_approved_evolution(vid)["reason"] == "no_pending_evolution"

    # a claim won but a genome save that fails releases the approval, audibly
    _record("approved")
    store["vsb"]["evolution_pending_cca"] = vcid
    def _boom(v):
        raise OSError("disk full")
    monkeypatch.setattr(V, "_save_vsb", _boom)
    try:
        V.apply_approved_evolution(vid)
        assert False, "the save failure must surface"
    except OSError:
        pass
    released = CC._load_change(vcid)
    assert released["status"] == "approved"
    assert any(e["event"] == "apply_failed_claim_released" for e in released["audit_trail"])

    # a stranded claim (record implemented by the apply, no mutation carrying its id) is named
    monkeypatch.setattr(V, "_save_vsb", _save)
    atomic_write_json(CC._cca_path(vcid), dict(released, status="implemented", audit_trail=released["audit_trail"] + [
        {"event": "implemented", "ts": "2026-09-13T00:00:09Z", "by": "vsb_evolution_apply", "by_verified": False}]))
    store["vsb"] = dict(store["vsb"], evolution_pending_cca=vcid, applied_mutations=[])
    assert V.apply_approved_evolution(vid)["reason"] == "claim_stranded"


def test_w460_compliance_badges_are_evaluated_or_absent(client):
    """§6/§7 + §11 (ledger 1.12 · R4.3) — the Visual Composer tab was a local canvas whose nodes reached no
    swarm, seeded with fictional model names, printing a green "GaaS COMPLIANT" for nodes nobody evaluated;
    a second copy (Agent Forge) shipped in the channels dock. Across the app, a dozen more surfaces
    claimed compliance nobody computed: a session that "conforms to Floor 24 mandates", a green IDLE veto
    window and a 0.08 / 0.1 privacy budget that exist nowhere, a model-invented "GaaS Alignment" score,
    a green NOMINAL when the status call never answered, "every action is governed", an "autonomous,
    compliant" entity, and a Governance Hub that painted a blocked action's halt as a green CHAINED.

    Both ways: every unevaluated claim is gone from the code that renders (comments are stripped), AND the
    badges that ARE evaluated still render conditionally on a real verdict; the Governance Hub's flag is
    computed from what each event is, and a genuinely allowed action still reads as recorded.
    """
    import re
    from pathlib import Path
    from agentic_core.gaas.v5.ueg import classify_event

    # one pass that keeps string literals and removes only real comments: a '/*' inside a string
    # (accept="image/*", '*/*') is not a comment start, and a comment quoting a marker is still a comment
    _tok = re.compile(r"""('(?:\\.|[^'\\\n])*'|"(?:\\.|[^"\\\n])*"|`(?:\\.|[^`\\])*`)|/\*.*?\*/|//[^\n]*""", re.S)

    def _strip_comments(text: str) -> str:
        return _tok.sub(lambda m: m.group(1) or " ", text)

    # the stripper itself, both ways — it must never hide code, and must remove what is only a comment
    assert "GaaS COMPLIANT" in _strip_comments("fetch(u, { headers: { Accept: '*/*' } }); <b>GaaS COMPLIANT</b> {/* x */}")
    assert "GaaS COMPLIANT" in _strip_comments('<input accept="image/*" /> <b>GaaS COMPLIANT</b> {/* x */}')
    assert "GaaS COMPLIANT" not in _strip_comments('const a = 1; // removed the old "GaaS COMPLIANT" badge')
    assert "GaaS COMPLIANT" not in _strip_comments("return x/* GaaS COMPLIANT */;")
    assert "http://h/x" in _strip_comments("const u = 'http://h/x';")

    roots = [Path("apps/workstation-superapp/src"), Path("packages/ui/src"), Path("packages/shared")]
    MARKERS = {
        r"(?i)GaaS(?:\s|\{['\"] ['\"]\}|&nbsp;)+COMPLIANT": "a compliance badge nothing evaluated",
        r"Nematron|Nemoclaw": "fictional model names",
        r"(?i)session conforms to": "a per-session conformance nobody computes",
        r"Every action is governed": "a tour claim that every action passes the gate",
        r"GaaS Alignment": "a model-invented compliance score",
        r"Constitutional compliance \(gaas\.v5\)": "a browser-built plan claiming compliance",
        r"(?i)self-healing is active": "an autonomy claim",
        r"autonomous, compliant": "a compliance claim for every entity",
        r"Deliverable · compliant": "a stage rail claiming every output is compliant",
        r"auto-approved as a reflex": "a reflex nothing invokes",
        r"any action that ran ungated": "a claim that every ungated action is recorded",
        r"v16-Omega": "a literal engine name shown when the status call failed",
        r">IDLE<": "a veto window that does not exist",
        r"0\.08 / 0\.1": "a privacy budget that does not exist",
        r"valid:\s*true,\s*allowed:\s*true": "a client-side validator that approves everything",
    }
    offenders, scanned = [], {str(r): 0 for r in roots}
    for root in roots:
        for f in list(root.rglob("*.tsx")) + list(root.rglob("*.ts")):
            if "node_modules" in f.parts:
                continue
            scanned[str(root)] += 1
            code = _strip_comments(f.read_text(encoding="utf-8", errors="replace"))
            for pat, why in MARKERS.items():
                if re.search(pat, code):
                    offenders.append(f"{f}: {pat} ({why})")
    assert all(n >= 1 for n in scanned.values()) and sum(scanned.values()) >= 110, scanned   # the instrument is not blind (123 files at W460)
    assert not offenders, "\n".join(offenders)

    # the retired canvases are gone, their routes land on the real designer, which no status call can hide
    S = Path("apps/workstation-superapp/src")
    assert not (S / "components/organism/VisualAgentComposer.tsx").exists()
    assert not (S / "components/organism/AgentForge.tsx").exists()
    assert not Path("packages/shared/gaas.ts").exists()
    hub = (S / "pages/LivingOrganisationHub.tsx").read_text(encoding="utf-8")
    assert "VisualAgentComposer" not in hub and 'to="/native-ai?focus=cascade-designer"' in hub
    app = (S / "App.tsx").read_text(encoding="utf-8")
    assert '"/visual-composer"    element={<Navigate to="/native-ai?focus=cascade-designer" replace />}' in app
    assert "AgentForge" not in Path("packages/ui/src/CommandCenter.tsx").read_text(encoding="utf-8")
    nai = (S / "pages/developers/NativeAI.tsx").read_text(encoding="utf-8")
    status_open = nai.index("{status && (")
    status_close = nai.index("        </>\n      )}", status_open)
    assert nai.index('id="cascade-designer"') > status_close          # outside the status block
    assert "!stages.some(s => s.role.trim() && s.instruction.trim())" in nai  # no empty cascade from the page

    # POSITIVE — the badges that ARE evaluated still render, conditionally on the verdict
    api_ts = (S / "lib/api.ts").read_text(encoding="utf-8")
    assert "overall === 'pass' ? 'bg-emerald-500/15 text-emerald-400' : 'bg-slate-800 text-slate-500'" in api_ts
    rfab = (S / "pages/synthesis/ResourceFabric.tsx").read_text(encoding="utf-8")
    assert "gov (intent only): {runResult.org_cascade.governance}" in rfab                 # a constant verdict is never green
    assert "runResult.org_cascade.governance === 'allowed' ? 'bg-emerald" not in rfab
    chip = [ln for ln in rfab.splitlines() if "gov (intent only)" in ln]
    assert len(chip) == 1 and "emerald" not in chip[0]                               # no green, conditional or static
    # the colour fixes, pinned (each was a green claim on something nobody evaluated)
    pins = {
        "pages/enterprise/BoardOfDirectors.tsx": "<ShieldCheck size={12} className=\"text-slate-500\" /> {result.directive_id}",
        "pages/enterprise/VSBCockpit.tsx": "chiefResult.governance?.status === 'allowed' ? 'text-emerald-400'",
        "pages/enterprise/VSBEconomy.tsx": "gov === 'allowed' ? 'text-emerald-400' : gov ? 'text-amber-400' : 'text-slate-500'",
        "pages/governance/ComplianceChecker.tsx": "STATUS_ICON[v.status] ?? MinusCircle",
        "pages/synthesis/GenesisJourney.tsx": "m > 0 && n === m ? 'text-emerald-400' : m === 0 ? 'text-slate-500' : 'text-amber-400'",
        "components/layout/Header.tsx": "text-slate-300 hover:text-white hover:scale-105 transition-all gaas-audit-btn",
        "pages/governance/GovernanceHub.tsx": "color={!verify ? 'text-slate-500' : verify.valid ? 'text-emerald-500' : 'text-vital'}",
        "pages/governance/ConstitutionalUI.tsx": ".catch(() => setGaas(null))",
        "pages/enterprise/VSBSpawnStudio.tsx": "ev.data?.passed === true ? STAGE_META.gaas_complete",
    }
    for rel, needle in pins.items():
        assert needle in (S / rel).read_text(encoding="utf-8"), rel
    assert "compliance_score" not in Path("agentic_core/synthesis/api.py").read_text(encoding="utf-8")
    vsb_src = Path("agentic_core/api/vsb.py").read_text(encoding="utf-8")
    assert "gaas_passed = None" in vsb_src and "'NOT EVALUATED'" in vsb_src     # an unevaluated spawn gate never reads PASSED
    assert not re.search(r"^\s*gaas_passed = True\s*$", vsb_src, flags=re.M)      # never starts as PASSED
    assert "<CheckCircle2 size={20} className=\"text-emerald-500 opacity-20" not in (S / "pages/governance/ConstitutionalUI.tsx").read_text(encoding="utf-8")
    cui = (S / "pages/governance/ConstitutionalUI.tsx").read_text(encoding="utf-8")
    assert "'UNAVAILABLE'" in cui and "gaas.circuit_breaker.tripped ? 'BREAKER OPEN' : 'NOMINAL'" in cui
    gh = (S / "pages/governance/GovernanceHub.tsx").read_text(encoding="utf-8")
    assert "e?.flag?.level" in gh and "verify.valid ? 'VALID' : 'BROKEN'" in gh
    assert "d.decision === 'deny'" not in gh

    # BEHAVIOUR — the flag is what the event IS
    assert classify_event({"type": "policy_gate_halt"})["level"] == "flagged"
    assert classify_event({"type": "circuit_breaker_trip"})["level"] == "flagged"
    assert classify_event({"type": "compliance.screen", "overall": "fail"})["level"] == "flagged"
    assert classify_event({"type": "compliance.screen", "overall": "review"})["level"] == "review"
    assert classify_event({"type": "compliance.screen", "overall": "pass"})["level"] == "recorded"
    assert classify_event({"type": "compliance.screen", "overall": None})["level"] == "review"      # a screen that never ran
    assert classify_event({"type": "economy.materiality_gate_error"})["level"] == "flagged"
    assert classify_event({"type": "economy.materiality_hold_filed"})["level"] == "review"
    assert classify_event({"type": "checkpoint"})["level"] == "recorded"
    # drift: every adverse event type any producer writes is classified as flagged or review
    adverse = re.compile(r"halt|trip|fail|bypass|blocked|breach|refus|denied|violation|reject|hold|error")
    produced = set()
    for f in Path("agentic_core").rglob("*.py"):
        for m in re.finditer(r'"type":\s*"([a-z0-9_.]+)"', f.read_text(encoding="utf-8", errors="replace")):
            if adverse.search(m.group(1)):
                produced.add(m.group(1))
    assert len(produced) >= 10, produced                                   # the drift check is not blind
    unclassified = sorted(t for t in produced if classify_event({"type": t})["level"] == "recorded")
    assert not unclassified, unclassified

    # …and through the API: a blocked action's events are flagged, a genuinely allowed one is recorded
    try:
        blocked = client.post("/api/v1/gaas/intercept", json={
            "action_type": "w460_probe", "requires_human": True, "human_approved": False}).json()
        assert blocked["status"] == "blocked", blocked
        evs = client.get("/api/v1/gaas/ueg/events", params={"limit": 10}).json()["events"]
        assert all("flag" in e for e in evs)
        halts = [e for e in evs if (e.get("data") or {}).get("type") in ("policy_gate_halt", "circuit_breaker_trip")]
        assert halts and all(e["flag"]["level"] == "flagged" for e in halts)
        client.post("/api/v1/gaas/breaker/reset")
        ok = client.post("/api/v1/gaas/intercept", json={"action_type": "w460_harmless_probe"}).json()
        assert ok["status"] == "allowed", ok
        latest = client.get("/api/v1/gaas/ueg/events", params={"limit": 3}).json()["events"]
        assert any(e["flag"]["level"] == "recorded" for e in latest)
    finally:
        client.post("/api/v1/gaas/breaker/reset")                        # the breaker is shared — leave it closed
    assert client.get("/api/v1/gaas/status").json()["circuit_breaker"]["tripped"] is False

    # the designer's backend refuses a cascade that could never run, and still saves one that can
    assert client.post("/api/v1/resources/swarm/define", json={"name": "w460 empty", "stages": []}).status_code == 400
    assert client.post("/api/v1/resources/swarm/define", json={
        "name": "w460 blank", "stages": [{"role": "analyst", "instruction": "   "}]}).status_code == 400
    good = client.post("/api/v1/resources/swarm/define", json={
        "name": "w460 ok", "stages": [{"role": "analyst", "instruction": "List three risks."}]})
    assert good.status_code == 200 and good.json()["id"]
    # …and a saved cascade cannot be EDITED into one that define would refuse
    sid = good.json()["id"]
    assert client.put(f"/api/v1/resources/swarm/{sid}", json={
        "stages": [{"role": "analyst", "instruction": "   "}]}).status_code == 400
    assert client.put(f"/api/v1/resources/swarm/{sid}", json={
        "context": "edited context", "stages": [{"role": "analyst", "instruction": "List four risks."}]}).status_code == 200
    # the designer edits what is saved (context loaded and sent) and scrolls only once the page has settled
    assert "setDesignContext(c.context ?? '')" in nai and "{ name, context: designContext, stages: valid }" in nai
    assert "}, [loading, status]);" in nai and "window.setTimeout(() => document.getElementById('cascade-designer')?.scrollIntoView({ block: 'start' }), 250)" not in nai
    assert "if (r.ok || (editingId && r.status === 404)) { setEditingId(null);" in nai and 'data-testid="cascade-edit-mode"' in nai

    # second refutation — the same unevaluated-verdict class on the paths F1 did not touch
    import asyncio as _asyncio
    from types import SimpleNamespace
    from agentic_core.api import genesis as _genesis
    gen_src = Path("agentic_core/api/genesis.py").read_text(encoding="utf-8")
    assert '"constitutional_alignment": gov.status == "allowed"' not in gen_src      # the gate never reads the enterprise
    assert gen_src.count("**_establish_gate(gov)") == 2 and '"Constitutionally Attested"' not in gen_src
    for st in ("allowed", "halted", "blocked"):
        g = _genesis._establish_gate(SimpleNamespace(status=st, checkpoint_id="cp"))
        assert g["constitutional_alignment"] is None and g["constitutional_gate"]["status"] == st
        assert "not screened" in g["constitutional_gate"]["scope"]
    # the spawn gate follows the validator's OWN verdict: passed=False with no violations is not a pass
    from agentic_core.api import vsb as _vsb
    class _BelowThreshold:
        async def validate_intent(self, intent, context):
            return {"passed": False, "blocked": False, "violations": []}
    _saved = _vsb._gaas
    try:
        _vsb._gaas = _BelowThreshold()
        spawn = client.post("/api/v1/vsb/spawn", json={"challenge": "w460 threshold probe", "domain": "business"})
        gaas_events = [ln for ln in spawn.text.splitlines() if '"gaas_complete"' in ln]
        assert gaas_events and '"passed": false' in gaas_events[0] and '"evaluated": true' in gaas_events[0], gaas_events
    finally:
        _vsb._gaas = _saved
    gh2 = (S / "pages/governance/GovernanceHub.tsx").read_text(encoding="utf-8")
    assert "value={events.filter(e => flagLevel(e) === 'flagged').length}" in gh2 and "'Flagged + review'" in gh2
    assert "{gaas?.ueg?.total_events ?? '—'}" in cui
    gj = (S / "pages/synthesis/GenesisJourney.tsx").read_text(encoding="utf-8")
    assert "compliance: not screened" in gj and "not a certification" in gj
    assert "more living entities are not shown here" in (S / "pages/enterprise/VSBEconomy.tsx").read_text(encoding="utf-8")


def test_w462_followup_register_is_scheduled_and_in_lockstep(tmp_path):
    """W462 — a task a round finds and does not do used to live in a chat chip, a "NOT DONE, and why"
    paragraph or a commit message, and nothing made a later round pick it up. The register
    (docs/FOLLOWUPS.json) slots each one to the plan item whose round does it, or OWNER (NEXT was retired
    W469 — see test_w469_…), and the schedule is derived from the plan's own item order.

    Both ways: the REAL register passes check(), both plan docs carry exactly the rendered block (each in
    its own line endings, read as bytes), and the API serves the same schedule; then synthetic registers
    prove each rule bites — a row on a DONE item, a mis-spelled DONE marker, a cross-reference that is not
    a DONE marker, an unknown slot, owner-gated work slotted anywhere but OWNER, a done row with no round,
    a dropped row with no reason, an open row with closed_by, a file not in the repository (or named with
    backslashes), malformed rows REPORTED rather than raised, one-line text, a duplicated or misplaced
    marker block, and either doc's block edited by hand. The schedule follows plan order (P1.13 before
    P2.x; a retired NEXT row is reported unscheduled) and never schedules an owner-gated row; the API reports a broken or unreadable
    register instead of a 500; the page names each state.
    """
    import json as _json
    import pathlib

    from fastapi.testclient import TestClient

    from agentic_core import plan_followups as fu
    from agentic_core.app_mvp import app

    # the guard validates THIS repository's register — never an inherited scratch root
    assert fu.ROOT.resolve() == pathlib.Path(__file__).resolve().parents[1], fu.ROOT
    reg = fu.load()
    raw_register = fu.REGISTER.read_bytes()
    prompt = fu.read_doc(fu.PROMPT)
    living = fu.read_doc(fu.LIVING)

    # ── the real register: clean, rendered into both docs, served by the API ──
    assert fu.check(reg, prompt, living) == [], fu.check(reg, prompt, living)
    items = fu.plan_items(prompt)
    slots = [i["slot"] for i in items]
    assert slots.index("P1.1") < slots.index("P1.14") < slots.index("P2.1") < slots.index("P4.6")
    assert len(slots) == len(set(slots)) >= 30
    assert {"P1.1", "P1.11", "P1.12"} <= {i["slot"] for i in items if i["done"]}
    assert "\r\n" in living.split(fu.BEGIN, 1)[1].split(fu.END, 1)[0], "the living plan's block must keep CRLF"
    assert "\r\n" not in prompt, "the prompt is LF (read as bytes, so this can fail)"
    # the block sits INSIDE the real delivery plan section (the tag line, not a prose mention of it)
    assert prompt.index("\n<delivery_plan>\n") < prompt.index(fu.BEGIN) < prompt.index("\n</delivery_plan>\n")
    assert fu.BEGIN in fu.delivery_plan_body(prompt)

    client = TestClient(app)
    body = client.get("/api/v1/plan/followups").json()
    s = fu.schedule(reg, prompt)
    assert body["available"] is True and body["integrity"] == {"ok": True, "problems": []}
    assert body["counts"] == s["counts"] and s["counts"]["open"] > 0
    assert [x["slot"] for x in body["schedule"]] == [x["slot"] for x in s["schedule"]]
    assert body["next_plan_item"] == next(i["slot"] for i in items if not i["done"])
    plan = client.get("/api/v1/plan").json()
    assert plan["followups"]["open"] == s["counts"]["open"]
    assert plan["followups"]["api"] == "/api/v1/plan/followups"

    # ── synthetic registers: each rule bites ──
    first_open = next(i["slot"] for i in items if not i["done"])
    done_slot = next(i["slot"] for i in items if i["done"])

    def row(**kw):
        base = {"id": "FU-900", "title": "t", "why": "w", "source": "test", "found": "2026-09-13",
                "files": [], "severity": "medium", "owner_gated": False, "slot": first_open,
                "status": "open", "closed_by": None, "note": ""}
        base.update(kw)
        return base

    def problems(rows, doc_prompt=None, doc_living=None):
        r = {"items": rows} if isinstance(rows, list) else rows
        text = doc_prompt if doc_prompt is not None else fu.splice_all(prompt, r, prompt)
        return fu.check(r, text, doc_living)

    def has(ps, needle):
        return any(needle in x for x in ps)

    tracked_file = "agentic_core/api/living_plan.py"
    assert problems([row(slot=first_open)]) == []
    assert has(problems([row(slot=done_slot)]), "already DONE")
    assert has(problems([row(slot="P9.9")]), "not a delivery-plan item")
    assert has(problems([row(status="done")]), "closed_by")
    assert problems([row(status="done", closed_by="W462", slot=done_slot)]) == []
    assert has(problems([row(status="dropped")]), "without a note")
    assert has(problems([row(closed_by="W461")]), "open but closed_by is set")
    assert has(problems([row(files=["agentic_core/no_such_file.py"])]), "not in the working tree")
    assert problems([row(files=[tracked_file])]) == []
    assert has(problems([row(files=[tracked_file.replace("/", "\\")])]), "forward slashes")
    assert has(problems([row(files=[tracked_file.upper()])]), "not in the working tree")      # exact case, as on CI
    assert has(problems([row(files=["agentic_core/api"])]), "not in the working tree")          # a directory is not a file
    # the working tree AND the index: an unstaged deletion and an untracked file are both caught
    _real_tracked = fu._tracked
    try:
        fu._tracked = lambda root: {"agentic_core/deleted_but_still_indexed.py", tracked_file}
        assert has(problems([row(files=["agentic_core/deleted_but_still_indexed.py"])]), "not in the working tree")
        fu._tracked = lambda root: set()
        assert has(problems([row(files=[tracked_file])]), "git does not track yet")
        fu._tracked = lambda root: None                      # no git: the exact-case file walk alone decides
        assert problems([row(files=[tracked_file])]) == []
        assert has(problems([row(files=[tracked_file.upper()])]), "not in the working tree")
        assert has(problems([row(files=["agentic_core/api"])]), "not in the working tree")
    finally:
        fu._tracked = _real_tracked
    assert has(problems([row(owner_gated=True, slot="NEXT")]), "slotted OWNER")                # not the retired NEXT…
    assert has(problems([row(owner_gated=True, slot=first_open)]), "slotted OWNER")             # …nor a plan item
    assert has(problems([row(owner_gated=True, slot=done_slot)]), "slotted OWNER")              # …nor a DONE one
    assert problems([row(owner_gated=True, slot="OWNER")]) == []
    assert has(problems([row(slot="OWNER")]), "owner_gated is false")
    assert has(problems([row(), row()]), "duplicate")
    assert has(problems([row(), row(id="FU-900 ")]), "duplicate")                              # a hand-typed near-copy
    # one malformed row never switches the other rules off
    mixed_bad = problems([row(id="FU-901", severity="urgent"), row(id="FU-902", slot=done_slot)])
    assert has(mixed_bad, "severity") and has(mixed_bad, "already DONE")
    # malformed rows are REPORTED, never raised
    assert has(problems([row(severity="urgent")]), "severity")
    assert has(problems([row(owner_gated="false")]), "owner_gated must be true or false")
    assert has(problems([row(files="agentic_core")]), "files must be a list")
    assert has(problems([row(why="first line\r\nsecond line")]), "must be one line")
    missing_why = row()
    del missing_why["why"]
    assert has(fu.check({"items": [missing_why]}, prompt, living), "missing why")
    assert has(fu.check({"items": ["not a row"]}, prompt, living), "not an object")
    assert has(fu.check({"items": None}, prompt, living), "items list")
    assert has(fu.check([row()], prompt, living), "items list")
    assert fu.schedule({"items": None}, prompt)["counts"]["open"] == 0

    # the plan's DONE marker: exactly '✅ DONE W###' right after the id; anything else is reported
    variant = prompt.replace(f"\n {first_open} [", f"\n {first_open} ✅ Done W999 [", 1)
    assert variant != prompt
    assert not next(i for i in fu.plan_items(variant) if i["slot"] == first_open)["done"]
    assert has(fu.check({"items": []}, fu.splice(variant, fu.render({"items": []}, variant))), "says done")
    for form in ("Done W470 [", "done - W470 [", "[x] ✅ DONE W470 ["):                    # any other form or place
        other = prompt.replace(f"\n {first_open} [", f"\n {first_open} {form}", 1)
        assert other != prompt and not next(i for i in fu.plan_items(other) if i["slot"] == first_open)["done"]
        assert has(fu.check({"items": []}, fu.splice(other, fu.render({"items": []}, other))), "says done"), form
    idiom = prompt.replace(f"\n {first_open} [", f"\n {first_open} DONE WHEN the Owner rules [", 1)
    assert not has(fu.check({"items": []}, fu.splice(idiom, fu.render({"items": []}, idiom))), "says done")
    twice = prompt.replace(f"\n {first_open} [", f"\n {first_open} [x]\n {first_open} [", 1)
    assert has(fu.check({"items": []}, fu.splice(twice, fu.render({"items": []}, twice))), "appears 2 times")
    xref = prompt.replace(f"\n {first_open} [", f"\n {first_open} (see P1.1 ✅ DONE W449) [", 1)
    assert not next(i for i in fu.plan_items(xref) if i["slot"] == first_open)["done"]    # a cross-reference is not a marker

    # lockstep: either doc's block edited by hand, a duplicated block, a block outside the delivery plan
    rows = [row(slot=first_open)]
    block = fu.render({"items": rows}, prompt)
    good_p, good_l = fu.splice_all(prompt, {"items": rows}, prompt), fu.splice_all(living, {"items": rows}, prompt)
    assert problems(rows, good_p, good_l) == []
    # (W478: a rendered row now carries its priority, 'FU-900 [medium] [p …] t' — the probe edits the severity tag itself,
    # and asserts the edit landed, so it can never again be a no-op that the lockstep check trivially 'passes')
    assert good_p.count("FU-900 [medium]") >= 1 and good_l.count("FU-900 [medium]") >= 1
    assert has(problems(rows, good_p.replace("FU-900 [medium]", "FU-900 [low]"), good_l), "delivery plan's follow-up block")
    assert has(problems(rows, good_p, good_l.replace("FU-900 [medium]", "FU-900 [low]")), "living plan's follow-up block")
    dup = good_l + "\r\n" + fu.BEGIN + "\r\nstale\r\n" + fu.END + "\r\n"
    assert has(problems(rows, good_p, dup), "exactly one follow-up marker pair")
    try:
        fu.splice(dup, block)
        raise AssertionError("splice must refuse a doc with two marker blocks")
    except ValueError:
        pass
    moved = good_p.replace(fu.BEGIN + "\n" + block + "\n" + fu.END, "")
    moved = moved.replace("\n<delivery_plan>\n", "\n" + fu.BEGIN + "\n" + block + "\n" + fu.END + "\n<delivery_plan>\n", 1)
    assert has(problems(rows, moved, good_l), "inside the <delivery_plan> section")

    # ordering: plan order; severity before age inside a slot (ids as numbers); owner rows never scheduled; a row on
    # the retired NEXT is reported (check) and listed unscheduled, never silently dropped (W469)
    later = next(i["slot"] for i in items if not i["done"] and i["slot"] != first_open)   # (W473: P1 is complete; the next open item after the first)
    mixed = {"items": [row(id="FU-901", slot=later), row(id="FU-1000", slot=first_open, severity="low"),
                       row(id="FU-999", slot=first_open, severity="low"),
                       row(id="FU-903", slot=first_open, severity="high"), row(id="FU-904", slot="NEXT"),
                       row(id="FU-905", slot="OWNER", owner_gated=True)]}
    assert has(problems(mixed["items"]), "FU-904: slot NEXT is retired")
    assert problems([x for x in mixed["items"] if x["id"] != "FU-904"]) == []
    sch = fu.schedule(mixed, prompt)
    assert [x["slot"] for x in sch["schedule"]] == [first_open, later]
    assert [r["id"] for r in sch["schedule"][0]["items"]] == ["FU-903", "FU-999", "FU-1000"]
    assert [r["id"] for r in sch["unscheduled"]] == ["FU-904"]
    assert [r["id"] for r in sch["awaiting_owner"]] == ["FU-905"]
    assert sch["counts"] == {"open": 6, "scheduled": 4, "unscheduled": 1, "high": 1, "awaiting_owner": 1, "done": 0,
                             "dropped": 0}
    # defence in depth: even a hand-edited owner-gated row on a plan item is never scheduled (check reports it too)
    stray = fu.schedule({"items": [row(id="FU-906", slot=later, owner_gated=True)]}, prompt)
    assert stray["schedule"] == [] and [r["id"] for r in stray["awaiting_owner"]] == ["FU-906"]

    # the API reports a broken register and an unreadable one instead of a 500; /plan never fails because of it
    real_register = fu.REGISTER
    try:
        bad_file = tmp_path / "bad.json"
        bad_file.write_text(_json.dumps({"items": [row(slot=done_slot)]}), encoding="utf-8")
        fu.REGISTER = bad_file
        bad = client.get("/api/v1/plan/followups").json()
        assert bad["available"] is True and bad["integrity"]["ok"] is False
        assert has(bad["integrity"]["problems"], "already DONE")
        malformed = tmp_path / "malformed.json"
        malformed.write_text(_json.dumps({"items": [missing_why, "not a row"]}), encoding="utf-8")
        fu.REGISTER = malformed
        mal = client.get("/api/v1/plan/followups")
        assert mal.status_code == 200 and mal.json()["integrity"]["ok"] is False
        assert client.get("/api/v1/plan").status_code == 200
        broken = tmp_path / "broken.json"
        nan = tmp_path / "nan.json"
        nan.write_text('{"items": [{"severity": NaN}]}', encoding="utf-8")
        fu.REGISTER = nan
        nanr = client.get("/api/v1/plan/followups")
        assert nanr.status_code == 200 and nanr.json()["available"] is False and "not valid JSON" in nanr.json()["reason"]
        broken.write_text("{ not json", encoding="utf-8")
        fu.REGISTER = broken
        nj = client.get("/api/v1/plan/followups").json()
        assert nj["available"] is False and "not valid JSON" in nj["reason"]
        fu.REGISTER = real_register
        _real_check = fu.check
        try:
            calls = []

            def _mid_write_once(*a, **k):                  # the first read fell between the CLI's two writes
                calls.append(1)
                return [fu.LOCKSTEP_PROMPT] if len(calls) == 1 else _real_check(*a, **k)
            fu.check = _mid_write_once
            settled = client.get("/api/v1/plan/followups").json()
            assert len(calls) == 2 and settled["integrity"] == {"ok": True, "problems": []}
        finally:
            fu.check = _real_check
        try:
            def _checker_defect(*a, **k):
                raise RuntimeError("checker defect")
            fu.check = _checker_defect
            crashed = client.get("/api/v1/plan/followups")
            assert crashed.status_code == 200 and crashed.json()["available"] is False
            assert "could not be checked (RuntimeError" in crashed.json()["reason"]
        finally:
            fu.check = _real_check
        real_living = fu.LIVING
        try:
            ansi = tmp_path / "ansi_living.md"
            ansi.write_bytes(living.encode("utf-8") + b"\r\nOwner\x92s note saved as ANSI\r\n")
            fu.LIVING = ansi
            enc = client.get("/api/v1/plan/followups")
            assert enc.status_code == 200 and enc.json()["available"] is False and "not valid UTF-8" in enc.json()["reason"]
        finally:
            fu.LIVING = real_living
        fu.REGISTER = tmp_path / "absent.json"
        gone = client.get("/api/v1/plan/followups").json()
        assert gone["available"] is False and "not readable here" in gone["reason"]
        assert ":\\" not in gone["reason"] and "/" not in gone["reason"].split(" — ")[0], gone   # a file name, never a server path
        assert client.get("/api/v1/plan").json()["followups"]["available"] is False
    finally:
        fu.REGISTER = real_register
    assert fu.REGISTER.read_bytes() == raw_register            # nothing in this test wrote the register

    # ── the CLI, end to end, in a scratch copy (WORKSTATION_FOLLOWUPS_ROOT) — never against the repo ──
    import os as _os
    import subprocess as _sp
    import sys as _sys
    scratch = tmp_path / "root"
    (scratch / "docs").mkdir(parents=True)
    (scratch / "agentic_core" / "api").mkdir(parents=True)
    (scratch / "agentic_core" / "api" / "living_plan.py").write_bytes(b"# stand-in\n")
    empty = {"items": []}
    (scratch / "docs" / "FABLE_DELIVERY_PROMPT.md").write_bytes(fu.splice_all(prompt, empty, prompt).encode("utf-8"))
    (scratch / "docs" / "WORKSTATION_IDBO_LIVING_PLAN.md").write_bytes(fu.splice_all(living, empty, prompt).encode("utf-8"))
    (scratch / "docs" / "FOLLOWUPS.json").write_bytes(b'{"items": []}\n')
    cli_env = dict(_os.environ, WORKSTATION_FOLLOWUPS_ROOT=str(scratch), PYTHONIOENCODING="utf-8")
    script = str(pathlib.Path("scripts/followups.py").resolve())

    def cli(*argv):
        return _sp.run([_sys.executable, script, *argv], env=cli_env, capture_output=True, text=True, encoding="utf-8")

    def scratch_rows():
        return _json.loads((scratch / "docs" / "FOLLOWUPS.json").read_text(encoding="utf-8"))["items"]

    assert cli("check").returncode == 0
    racers = [_sp.Popen([_sys.executable, script, "add", "--title", f"racer {k}", "--why", "w", "--source", "test",
                         "--slot", first_open, "--files", "agentic_core\\api\\living_plan.py"],
                        env=cli_env, stdout=_sp.PIPE, stderr=_sp.PIPE) for k in range(3)]
    assert all(pr.wait(timeout=120) == 0 for pr in racers)
    got = scratch_rows()
    assert sorted(r["id"] for r in got) == ["FU-001", "FU-002", "FU-003"], got           # no id handed out twice, no row lost
    assert all(r["files"] == ["agentic_core/api/living_plan.py"] for r in got)            # backslashes normalised
    assert cli("check").returncode == 0                                                   # the docs moved with the register
    assert "note: WORKSTATION_FOLLOWUPS_ROOT is set" in cli("check").stderr          # an override always says so
    gated = cli("add", "--title", "a ruling", "--why", "w", "--source", "test", "--slot", first_open, "--owner-gated")
    assert gated.returncode == 0 and "slotted OWNER" in gated.stdout and scratch_rows()[-1]["slot"] == "OWNER"
    refused = cli("reslot", "FU-004", "--slot", first_open)
    assert refused.returncode != 0 and "pass --ungate once the Owner has ruled" in (refused.stdout + refused.stderr) and scratch_rows()[-1]["slot"] == "OWNER"
    assert cli("reslot", "FU-004", "--slot", first_open, "--ungate").returncode == 0
    assert scratch_rows()[-1]["slot"] == first_open and scratch_rows()[-1]["owner_gated"] is False
    before_bad = scratch_rows()
    bad_add = cli("add", "--title", "t", "--why", "w", "--source", "test", "--slot", "P9.9")
    assert bad_add.returncode == 1 and "REFUSED" in bad_add.stdout and scratch_rows() == before_bad
    assert cli("check").returncode == 0
    # a holder the OS has not released keeps the others out; a killed holder releases it (no stale takeover)
    holder = _sp.Popen([_sys.executable, "-c",
                        "import sys, time; sys.path.insert(0, sys.argv[1]); sys.argv = sys.argv[:1]; import followups; "
                        "cm = followups.register_lock(); cm.__enter__(); print('held', flush=True); time.sleep(60)",
                        str(pathlib.Path("scripts").resolve())], env=cli_env, stdout=_sp.PIPE, text=True)
    try:
        assert holder.stdout.readline().strip() == "held"
        blocked_env = dict(cli_env, FOLLOWUPS_LOCK_WAIT_S="1")
        waiting = _sp.run([_sys.executable, script, "close", "FU-001", "--by", "W999"], env=blocked_env,
                          capture_output=True, text=True, encoding="utf-8", timeout=120)
        assert waiting.returncode != 0 and "another followups.py is writing" in (waiting.stdout + waiting.stderr)
        reading = _sp.run([_sys.executable, script, "check"], env=blocked_env,       # a reader waits for the writer too
                          capture_output=True, text=True, encoding="utf-8", timeout=120)
        assert reading.returncode != 0 and "another followups.py is writing" in (reading.stdout + reading.stderr)
        assert scratch_rows()[0]["status"] == "open"
    finally:
        holder.kill()
        holder.wait(timeout=30)
    assert cli("close", "FU-001", "--by", "W999").returncode == 0 and scratch_rows()[0]["status"] == "done"
    # the lock file and write temps can never be committed
    ignored = _sp.run(["git", "check-ignore", "docs/FOLLOWUPS.json.lock", "docs/FABLE_DELIVERY_PROMPT.md.tmp"],
                      capture_output=True, text=True)
    assert ignored.returncode == 0 and len(ignored.stdout.split()) == 2, ignored
    # all or nothing: a write that fails part-way puts back what it already replaced
    a_file, b_file = tmp_path / "a.txt", tmp_path / "b.txt"
    a_file.write_bytes(b"a-old")
    b_file.write_bytes(b"b-old")
    _real_replace = fu.os.replace
    try:
        def _held(src, dst):
            if str(dst).endswith("b.txt"):
                raise PermissionError(13, "held by another process", str(dst))
            return _real_replace(src, dst)
        fu.os.replace = _held
        fu.REPLACE_TRIES, _tries = 2, fu.REPLACE_TRIES
        try:
            fu.write_all([(a_file, b"a-old", b"a-new"), (b_file, b"b-old", b"b-new")])
            raise AssertionError("write_all must re-raise")
        except PermissionError:
            pass
        finally:
            fu.REPLACE_TRIES = _tries
    finally:
        fu.os.replace = _real_replace
    assert a_file.read_bytes() == b"a-old" and b_file.read_bytes() == b"b-old"
    assert not (tmp_path / "b.txt.tmp").exists()
    # an interrupt (Ctrl+C) mid-write is rolled back too, and leaves no temp
    try:
        def _interrupted(src, dst):
            if str(dst).endswith("b.txt"):
                raise KeyboardInterrupt
            return _real_replace(src, dst)
        fu.os.replace = _interrupted
        try:
            fu.write_all([(a_file, b"a-old", b"a-new"), (b_file, b"b-old", b"b-new")])
            raise AssertionError("write_all must re-raise the interrupt")
        except KeyboardInterrupt:
            pass
    finally:
        fu.os.replace = _real_replace
    assert a_file.read_bytes() == b"a-old" and b_file.read_bytes() == b"b-old"
    assert not (tmp_path / "b.txt.tmp").exists()
    # …and when a restore ALSO fails, the error names what still carries the change (never "nothing changed")
    a_file.write_bytes(b"a-old")
    held_now = {"b.txt"}
    try:
        def _held_twice(src, dst):
            if any(str(dst).endswith(n) for n in held_now):
                raise PermissionError(13, "held by another process", str(dst))
            return _real_replace(src, dst)
        fu.os.replace = _held_twice
        fu.REPLACE_TRIES, _tries = 1, fu.REPLACE_TRIES
        real_atomic = fu.atomic_write

        def _atomic_then_hold_a(path, data):
            real_atomic(path, data)
            if path == a_file:
                held_now.add("a.txt")                        # a reader grabbed a.txt right after it was replaced
        fu.atomic_write = _atomic_then_hold_a
        try:
            fu.write_all([(a_file, b"a-old", b"a-new"), (b_file, b"b-old", b"b-new")])
            raise AssertionError("write_all must re-raise")
        except fu.PartialWrite as exc:
            assert exc.unrestored == [a_file] and "not put back: a.txt" in str(exc)
        finally:
            fu.atomic_write = real_atomic
            fu.REPLACE_TRIES = _tries
    finally:
        fu.os.replace = _real_replace
    assert a_file.read_bytes() == b"a-new" and b_file.read_bytes() == b"b-old"
    # a failure names the file that is held, not the temp it tried to move
    try:
        fu.os.replace = lambda src, dst: (_ for _ in ()).throw(PermissionError(13, "held", str(dst)))
        fu.REPLACE_TRIES, _tries = 1, fu.REPLACE_TRIES
        try:
            fu.atomic_write(b_file, b"x")
            raise AssertionError("must raise")
        except PermissionError as exc:
            assert exc.filename == str(b_file) and "held open by another program" in str(exc)
        finally:
            fu.REPLACE_TRIES = _tries
    finally:
        fu.os.replace = _real_replace
    assert not (tmp_path / "b.txt.tmp").exists()

    # the page shows each state: the schedule, a register out of step, and a register it could not load
    page = pathlib.Path("apps/workstation-superapp/src/pages/TransformationDashboard.tsx").read_text(encoding="utf-8")
    assert "apiJson<Followups>('/api/v1/plan/followups')" in page and "Delivery plan — live" in page   # W469 renamed
    assert "{!followups.integrity.ok && (" in page and "The register is out of step with the plan" in page
    assert "{followups.reason ?? 'The follow-up register is not readable here.'}" in page


def test_w463_economy_approvals_release_only_what_they_were_filed_for(client, monkeypatch):
    """W463 (register FU-002 + its class) — a Change Control approval of a material economy action is filed
    by the economy, releases the intake it was filed for (no more), is spent once, and is given back only
    for that action when it did not run.

    What was wrong: the materiality gate accepted ANY approved record whose title matched (a LOW
    'config_minor' change submitted with the hold's title was auto-approved and released a 4,000,000-WST
    distribution); it released any amount and any counterparty; it returned a bare None both below the
    threshold and after spending an approval, so the restore re-discovered its target by title scan and ran
    even when nothing was consumed — a blocked NON-material transfer or cycle re-approved an approval an
    EARLIER action had spent, and the next material action spent it twice; the heartbeat spent an approval
    before its policy pre-gate and never gave it back; the cycle drained receipts that landed after the gate.
    The first W463 draft's refutation added: exact-amount binding filed a new hold on every beat while
    revenue arrived and stranded approvals that later released unrelated distributions; a rejection became a
    dead end; a smaller action could spend a larger approval; a raised cycle action was re-run under the same
    approval; a debited transfer could get its approval back through the funds re-check branch or a lenient
    ledger read. Virtual WST only.
    """
    import asyncio
    import json as _json
    import uuid as _uuid
    import pytest as _pytest

    import agentic_core.gaas.v5 as g5
    from agentic_core.api import change_control as cca
    from agentic_core.config import atomic_write_json
    from agentic_core.economy import governance as gv
    from agentic_core.economy import transfers as tr
    from agentic_core.economy.living_vsbs import operate_vsb, register
    from agentic_core.economy.metabolism import EconomicMetabolism
    from agentic_core.economy.revenue import peek_pending, record_event
    from agentic_core.gaas.v5.policy_gate import ConstitutionalPolicyGate
    from agentic_core.gaas.v5.ueg import classify_event

    events = []
    real_log = gv._ueg_log
    monkeypatch.setattr(gv, "_ueg_log", lambda e: (events.append(e), real_log(e))[1])
    THRESHOLD = 1000.0
    monkeypatch.setattr(gv, "MATERIALITY_WST", THRESHOLD)

    def uid(tag):
        return f"w463-{tag}-{_uuid.uuid4().hex[:6]}"

    def living(tag):
        v = uid(tag)
        register(v, f"W463 {tag}", "waqf_ltd_hybrid", "enterprise", "Rehan")
        return v

    def fund(v, revenue):                                   # a cycle run above the threshold funds the reserve
        monkeypatch.setattr(gv, "MATERIALITY_WST", 1e15)
        out = client.post("/api/v1/economy/cycle", json={"vsb_id": v, "entity_type": "waqf_ltd_hybrid",
                                                         "revenue": revenue, "costs": 0}).json()
        monkeypatch.setattr(gv, "MATERIALITY_WST", THRESHOLD)
        assert out["cycle"] is not None, out

    def decide(cid, verdict="approved"):
        # W464 — an economy hold is CRITICAL: the Owner's explicit decision carries the acknowledgement
        r = client.post(f"/api/v1/cca/{cid}/review", json={"override_decision": verdict, "reviewer_notes": "w463",
                                                         "admin_decision_for_critical": True})
        assert r.status_code == 200 and cca._load_change(cid)["status"] == verdict, r.text

    def rec(cid):
        return cca._load_change(cid)

    def trail(cid, event):
        return [e for e in (rec(cid).get("audit_trail") or []) if e.get("event") == event]

    def holds_for(v):
        return [c for c in (cca._load_change(x["cca_id"]) or {} for x in cca._list_changes())
                if c and c.get("vsb_id") == v and c.get("change_type") == "economy_material"]

    def transfer(a, b, amount):
        return client.post("/api/v1/economy/transfer", json={"from_vsb": a, "to_vsb": b, "amount": amount})

    class _Blocked:
        status, output, checkpoint_id = "blocked", None, "chk-w463"

    class _BlockingGov:
        def __init__(self, *a, **k): pass
        async def intercept(self, ctx, action): return _Blocked()

    class _ExecThenBlockGov:                                    # the action RAN, then the gate said blocked
        def __init__(self, *a, **k): pass
        async def intercept(self, ctx, action):
            await action()
            return _Blocked()

    real_gov = g5.UnifiedConstitutionalInterceptorV16Omega
    real_record = tr.record_transfer

    def with_gov(gov_cls, fn):
        g5.UnifiedConstitutionalInterceptorV16Omega = gov_cls
        try:
            return fn()
        finally:
            g5.UnifiedConstitutionalInterceptorV16Omega = real_gov

    def with_record(fake, fn):
        tr.record_transfer = fake
        try:
            return fn()
        finally:
            tr.record_transfer = real_record

    def raising(exc):
        def _f(*a, **k):
            raise exc
        return _f

    # ── FU-002 as registered: a blocked NON-material transfer must not resurrect a spent approval ──
    a, b, c = living("a"), living("b"), living("c")
    fund(a, 50000)                                                           # reserve 10,000
    held = transfer(a, b, 1500).json()
    id1 = held["governance"]["cca_id"]
    assert held["transfer"] is None and held["governance"]["status"] == "held_for_change_control"
    assert rec(id1)["est_distributable_wst"] == 1500.0 and rec(id1)["counterparty"] == b
    decide(id1)
    assert transfer(a, b, 1500).json()["transfer"]["amount_wst"] == 1500.0
    assert rec(id1)["status"] == "implemented" and len(trail(id1, "consumed_by_economy_cycle")) == 1
    failed_before = sum(1 for e in events if e.get("type") == "economy.materiality_approval_restore_failed")
    small = with_gov(_BlockingGov, lambda: transfer(a, b, 100).json())
    assert small["transfer"] is None and small["governance"]["status"] == "blocked"
    assert rec(id1)["status"] == "implemented" and not trail(id1, "approval_restored_action_never_ran")
    race = with_record(raising(ValueError("Insufficient virtual funds (w463 race)")), lambda: transfer(a, b, 100))
    assert race.status_code == 400 and rec(id1)["status"] == "implemented"      # the funds re-check path too
    # nothing consumed → nothing touched, and no adverse "restore failed" noise either
    assert sum(1 for e in events if e.get("type") == "economy.materiality_approval_restore_failed") == failed_before
    again = transfer(a, b, 1500).json()
    assert again["transfer"] is None and again["governance"]["cca_id"] not in (None, id1)   # a FRESH hold

    # ── …and a MATERIAL transfer that spent its approval and did not post gets exactly that one back ──
    id2 = again["governance"]["cca_id"]
    decide(id2)
    blocked = with_gov(_BlockingGov, lambda: transfer(a, b, 1500).json())
    assert blocked["transfer"] is None and rec(id2)["status"] == "approved" and "implemented_at" not in rec(id2)
    spent, restored = trail(id2, "consumed_by_economy_cycle"), trail(id2, "approval_restored_action_never_ran")
    assert len(spent) == 1 and len(restored) == 1 and restored[0]["consume_id"] == spent[0]["consume_id"]
    raced = with_record(raising(ValueError("Insufficient virtual funds (w463 race)")), lambda: transfer(a, b, 1500))
    assert raced.status_code == 400 and rec(id2)["status"] == "approved"                    # funds re-check site
    with _pytest.raises(RuntimeError):                                                      # raised before the debit
        with_record(raising(RuntimeError("w463 receiver vanished")), lambda: transfer(a, b, 1500))
    assert rec(id2)["status"] == "approved" and len(trail(id2, "approval_restored_action_never_ran")) == 3

    def _debit_then_raise(*x, **k):
        real_record(*x, **k)
        raise RuntimeError("w463 queue write failed after the debit")
    # W466 — a failure after the debit is answered from the ledger and the receiver's queue, never as a bare exception:
    # this one posted in full before it raised
    posted_then_failed = with_record(_debit_then_raise, lambda: transfer(a, b, 1500))
    assert posted_then_failed.status_code == 500 and posted_then_failed.headers["x-transfer-debited"] == "true"
    assert posted_then_failed.headers["x-transfer-receiver"] == "credited" and "do NOT re-run" in posted_then_failed.json()["detail"]
    assert rec(id2)["status"] == "implemented", "a transfer that DEBITED must never get its approval back"
    assert any(e.get("type") == "economy.materiality_approval_spent_cycle_failed" and e.get("cca_id") == id2
               for e in events)

    # the funds re-check branch asks the ledger too (a debit then a ValueError keeps the approval spent)
    id2b = transfer(a, b, 1400).json()["governance"]["cca_id"]
    decide(id2b)

    def _debit_then_valueerror(*x, **k):
        real_record(*x, **k)
        raise ValueError("w463 refused after the debit")
    refused_after = with_record(_debit_then_valueerror, lambda: transfer(a, b, 1400))
    assert refused_after.status_code == 500 and refused_after.headers["x-transfer-debited"] == "true"   # W466: it posted
    assert rec(id2b)["status"] == "implemented", "the ValueError branch gave back a debited transfer's approval"

    # a replay of a debited transfer repairs the receiver leg instead of being refused by the funds pre-check
    d, e_ = living("d"), living("e")
    fund(d, 10000)                                                           # reserve 2,000 < 2 × 1,500
    idd = transfer(d, e_, 1500).json()["governance"]["cca_id"]
    decide(idd)
    calls = {"n": 0}

    def _first_call_debits_then_raises(*x, **k):
        calls["n"] += 1
        out = real_record(*x, **k)
        if calls["n"] == 1:
            raise OSError("w463 pending store briefly unavailable")
        return out
    fixed = with_record(_first_call_debits_then_raises, lambda: transfer(d, e_, 1500))
    assert fixed.status_code == 200 and fixed.json()["transfer"] is not None, fixed.text
    assert fixed.json()["transfer"]["idempotent_replay"] is True and fixed.json()["transfer"]["replay_repaired_receiver_leg"] is False
    assert tr.peek_pending_transfers(e_) == 1500.0 and rec(idd)["status"] == "implemented"

    # a ledger that cannot be read is never "no debit"
    broken = uid("broken")
    from agentic_core.economy.ledger import VirtualLedger
    VirtualLedger(broken).path.write_text("{ half-written", encoding="utf-8")
    try:
        with _pytest.raises(Exception):
            tr.debit_posted(broken, "xfer-anything")
    finally:
        VirtualLedger(broken).path.unlink(missing_ok=True)   # W473 (FU-066) — never left for every later reconcile pass
    assert tr.debit_posted(uid("nobooks"), "xfer-anything") is False

    # ── the approval names its counterparty: consent for a→b does not release a→c ──
    to_b = transfer(a, b, 1200).json()
    id3 = to_b["governance"]["cca_id"]
    decide(id3)
    to_c = transfer(a, c, 1200).json()
    assert to_c["transfer"] is None and to_c["governance"]["cca_id"] not in (None, id3)
    assert rec(id3)["status"] == "approved"
    assert transfer(a, b, 1200).json()["transfer"] is not None and rec(id3)["status"] == "implemented"
    id4 = transfer(a, b, 1100).json()["governance"]["cca_id"]
    decide(id4)
    with_gov(_ExecThenBlockGov, lambda: transfer(a, b, 1100))
    assert rec(id4)["status"] == "implemented", "a transfer that posted must never get its approval back"

    # ── one live hold per action: a growing request keeps ONE hold current; a larger one withdraws the approval ──
    x = uid("cycle")
    cyc = lambda revenue, costs=0: client.post("/api/v1/economy/cycle", json={
        "vsb_id": x, "entity_type": "waqf_ltd_hybrid", "revenue": revenue, "costs": costs}).json()
    idc1 = cyc(5000)["governance"]["cca_id"]
    assert rec(idc1)["est_distributable_wst"] == 4000.0
    assert cyc(5100)["governance"]["cca_id"] == idc1 and rec(idc1)["est_distributable_wst"] == 4080.0
    assert trail(idc1, "amount_rebound") and len(holds_for(x)) == 1                # re-estimated, no sibling
    decide(idc1)
    big = cyc(50000)
    idc2 = big["governance"]["cca_id"]
    assert big["cycle"] is None and idc2 not in (None, idc1)
    assert rec(idc1)["status"] == "withdrawn" and trail(idc1, "withdrawn_superseded")[0]["superseded_by"] == idc2
    assert cyc(5000)["governance"]["cca_id"] == idc2 and rec(idc2)["est_distributable_wst"] == 4000.0
    decide(idc2)
    assert cyc(4000)["cycle"] is not None and rec(idc2)["status"] == "implemented"   # within what was approved
    # a blocked NON-material cycle does not re-approve anything
    with_gov(_BlockingGov, lambda: cyc(10))
    assert rec(idc2)["status"] == "implemented" and not trail(idc2, "approval_restored_action_never_ran")
    # a blocked MATERIAL cycle gives back exactly what it spent; one that ran does not
    idc3 = cyc(5000)["governance"]["cca_id"]
    decide(idc3)
    assert with_gov(_BlockingGov, lambda: cyc(5000))["cycle"] is None
    assert rec(idc3)["status"] == "approved" and len(trail(idc3, "approval_restored_action_never_ran")) == 1
    with_gov(_ExecThenBlockGov, lambda: cyc(5000))
    assert rec(idc3)["status"] == "implemented", "a cycle that ran must never get its approval back"
    # a stale handle is skipped — the record's latest spend is not that one — and a reviewer sees it
    gv._restore_consumed_approval({"cca_id": idc3, "consume_id": "consume-stale"}, vsb_id=x, reason="w463 stale")
    assert rec(idc3)["status"] == "implemented"
    skip = [e for e in events if e.get("type") == "economy.materiality_approval_restore_skipped" and e.get("cca_id") == idc3]
    assert skip and skip[-1]["skip_reason"] == "spent_by_another_action"
    assert classify_event(skip[-1])["level"] == "review"

    # ── a cycle action that raised part-way is never re-run under the same approval (both paths) ──
    real_run = EconomicMetabolism.run_cycle
    runs = {"n": 0}

    def _run_raises(self, *aa, **kk):
        runs["n"] += 1
        # W467 — mid-cycle means AFTER the first ledger write: the stub reports that write, as run_cycle does (a cycle
        # that raises before writing anything hands the approval back — test_w467 covers that side)
        if isinstance(kk.get("progress"), dict):
            kk["progress"]["ledger_written"] = True
            if callable(kk["progress"].get("on_ledger_written")):
                kk["progress"]["on_ledger_written"]()
        raise RuntimeError("w463 ledger write failed mid-cycle")
    idc4 = cyc(6000)["governance"]["cca_id"]
    decide(idc4)
    EconomicMetabolism.run_cycle = _run_raises
    try:
        with _pytest.raises(RuntimeError):
            asyncio.run(gv.governed_cycle(x, "waqf_ltd_hybrid", "Rehan", 6000.0))
    finally:
        EconomicMetabolism.run_cycle = real_run
    assert runs["n"] == 1, "the raised cycle action was re-run by the fallback"
    assert rec(idc4)["status"] == "implemented" and not trail(idc4, "approval_restored_action_never_ran")
    assert any(e.get("type") == "economy.materiality_approval_spent_cycle_failed" and e.get("cca_id") == idc4 for e in events)
    hr = living("hraise")
    idh = gv.governed_cycle_sync(hr, "waqf_ltd_hybrid", "Rehan", 5000.0)["governance"]["cca_id"]
    decide(idh)
    EconomicMetabolism.run_cycle = _run_raises
    try:
        with _pytest.raises(RuntimeError):
            gv.governed_cycle_sync(hr, "waqf_ltd_hybrid", "Rehan", 5000.0)
    finally:
        EconomicMetabolism.run_cycle = real_run
    assert rec(idh)["status"] == "implemented"
    assert any(e.get("type") == "economy.materiality_approval_spent_cycle_failed" and e.get("cca_id") == idh for e in events)

    # ── a rejection answers exactly the action it was filed for; a changed action is asked again ──
    r_v = uid("reject")
    rcyc = lambda revenue: client.post("/api/v1/economy/cycle", json={"vsb_id": r_v, "revenue": revenue}).json()
    rid = rcyc(5_000_000)["governance"]["cca_id"]
    decide(rid, "rejected")
    same = rcyc(5_000_000)["governance"]
    assert same["status"] == "rejected_by_change_control" and same["cca_id"] == rid and len(holds_for(r_v)) == 1
    assert "submit a fresh request" not in same["note"]
    corrected = rcyc(5000)["governance"]
    assert corrected["status"] == "held_for_change_control" and corrected["cca_id"] != rid

    # an API-cycle approval is not spent by the same revenue declared with LOWER costs (a larger distributable)
    k_v = uid("costs")
    kcyc = lambda revenue, costs: client.post("/api/v1/economy/cycle", json={"vsb_id": k_v, "revenue": revenue,
                                                                             "costs": costs}).json()
    kid = kcyc(6000, 1000)["governance"]["cca_id"]
    decide(kid)
    lower = kcyc(6000, 0)
    assert lower["cycle"] is None and lower["governance"]["cca_id"] != kid and rec(kid)["status"] == "withdrawn"

    # ── the heartbeat: one hold kept current while revenue arrives; the approval releases the events it names ──
    h = living("heart")
    ev1 = record_event(h, "revenue", 5000.0, "marketplace", ref="w463-e1")
    first = operate_vsb(h)
    hid = first["governance"]["cca_id"]
    record_event(h, "revenue", 1.0, "marketplace", ref="w463-e2")
    second = operate_vsb(h)
    assert second["governance"]["cca_id"] == hid and len(holds_for(h)) == 1      # re-estimated, no sibling per sale
    decide(hid)
    record_event(h, "revenue", 7.0, "marketplace", ref="w463-e3")                 # lands after the approval
    ran = operate_vsb(h)
    assert "error" not in ran and ran.get("revenue_recognised_wst") == 5001.0, ran     # exactly the events it was filed for
    assert rec(hid)["status"] == "implemented"
    assert peek_pending(h)["revenue"] == 7.0, "the late sale must wait for the next cycle, not ride the approval"
    # a heartbeat approval is not spent by an API cycle (and vice versa)
    record_event(h, "revenue", 5000.0, "marketplace", ref="w463-e4")
    hid2 = operate_vsb(h)["governance"]["cca_id"]
    decide(hid2)
    api_try = client.post("/api/v1/economy/cycle", json={"vsb_id": h, "revenue": 5000}).json()
    assert api_try["cycle"] is None and api_try["governance"]["cca_id"] != hid2 and rec(hid2)["status"] == "approved"

    # ── the heartbeat path refuses BEFORE it spends: an approval survives a persistent refusal untouched ──
    trail_len = len(rec(hid2)["audit_trail"])
    real_validate = ConstitutionalPolicyGate.validate
    ConstitutionalPolicyGate.validate = lambda self, *aa, **kk: {"allowed": False, "reason": "w463 refusal"}
    try:
        for _ in range(2):
            assert operate_vsb(h)["governance"]["status"] == "blocked_by_gate"
    finally:
        ConstitutionalPolicyGate.validate = real_validate
    assert rec(hid2)["status"] == "approved" and len(rec(hid2)["audit_trail"]) == trail_len

    # ── nobody else can mint an economy approval — each identity clause on its own ──
    y = uid("forge")
    r422 = client.post("/api/v1/cca/submit", json={"title": gv._HOLD_TITLE_PREFIX + y, "change_type": "config_minor",
                                                  "description": "fix a typo"})
    assert r422.status_code == 422 and "reserved" in r422.json()["detail"]
    assert client.post("/api/v1/cca/submit", json={"title": "x", "change_type": "economy_material",
                                                   "description": "typo"}).status_code == 422
    assert client.post("/api/v1/cca/submit", json={"title": "[Economy] Rebalance the charity stage label",
                                                   "change_type": "config_minor", "description": "w463"}).status_code == 200
    base = {"title": gv._HOLD_TITLE_PREFIX + y, "change_type": "economy_material", "submitted_by": "economy:api",
            "vsb_id": y, "status": "approved", "impact_tier": "MEDIUM", "est_distributable_wst": 4000.0,
            "decision_source": "admin_override",   # W464 — the Owner's approval: each identity clause still refuses it
            "submitted_at": "2026-09-13T00:00:00Z", "description": "", "audit_trail": []}
    forged = {}
    for name, patch in {"type": {"change_type": "config_minor"}, "filer": {"submitted_by": "someone"},
                        "kind": {"submitted_by": "economy:heartbeat"}, "vsb": {"vsb_id": "another-vsb"},
                        "minted": {"submitted_by_verified": False}}.items():
        cid = f"cca-w463f{name}{_uuid.uuid4().hex[:4]}"
        atomic_write_json(cca._cca_path(cid), {**base, "cca_id": cid, **patch})
        forged[name] = cid
    fz = client.post("/api/v1/economy/cycle", json={"vsb_id": y, "revenue": 5000, "costs": 0}).json()
    assert fz["cycle"] is None and fz["governance"]["cca_id"] not in forged.values()
    assert all(rec(cid)["status"] == "approved" for cid in forged.values()), {n: rec(i)["status"] for n, i in forged.items()}

    # ── a record filed before W463: bound by the amount its description states, never unbound ──
    def legacy_record(v):
        cid = f"cca-w463legacy{_uuid.uuid4().hex[:4]}"
        atomic_write_json(cca._cca_path(cid), {
            k: val for k, val in {**base, "cca_id": cid, "vsb_id": v, "title": gv._HOLD_TITLE_PREFIX + v,
                                  "description": "Material virtual distribution: estimated distributable 4000.0 WST"}.items()
            if k != "est_distributable_wst"})                                    # the c519c497 shape: no amount field
        return cid
    lg = uid("legacy")
    legacy = legacy_record(lg)
    too_big = client.post("/api/v1/economy/cycle", json={"vsb_id": lg, "revenue": 5_000_000}).json()
    assert too_big["cycle"] is None and rec(legacy)["status"] == "withdrawn"
    lg2 = uid("legacy2")
    legacy2 = legacy_record(lg2)
    assert client.post("/api/v1/economy/cycle", json={"vsb_id": lg2, "revenue": 5000}).json()["cycle"] is not None
    assert rec(legacy2)["status"] == "implemented" and trail(legacy2, "consumed_by_economy_cycle")[0].get("amount_from_description")

    # ── a cycle drains only what the gate measured: a receipt landing after the gate waits (all run sites) ──
    q = living("payer")
    fund(q, 2_000_000)                                                      # reserve 400,000: four late receipts
    real_gate = gv._materiality_gate

    def late_receipt(p):
        def gate(vsb_id, est, source, counterparty=None, intake=None):
            out = real_gate(vsb_id, est, source, counterparty, intake)
            if vsb_id == p:
                real_record(q, p, 50000.0, "w463 late receipt")      # lands between the gate and the cycle
            return out
        return gate

    class _RaisingGov:
        def __init__(self, *aa, **kk): pass
        async def intercept(self, ctx, action): raise RuntimeError("w463 gate unavailable")

    class _NoOutput:
        status, output, checkpoint_id = "allowed", None, "chk-w463-none"

    class _NoOutputGov:
        def __init__(self, *aa, **kk): pass
        async def intercept(self, ctx, action): return _NoOutput()

    for label, runner in [
        ("sync", lambda p: gv.governed_cycle_sync(p, "waqf_ltd_hybrid", "Rehan", 0.0)),
        ("async action", lambda p: asyncio.run(gv.governed_cycle(p, "waqf_ltd_hybrid", "Rehan", 0.0))),
        ("async gate-raised fallback", lambda p: with_gov(_RaisingGov, lambda: asyncio.run(
            gv.governed_cycle(p, "waqf_ltd_hybrid", "Rehan", 0.0)))),
        ("async missing-output fallback", lambda p: with_gov(_NoOutputGov, lambda: asyncio.run(
            gv.governed_cycle(p, "waqf_ltd_hybrid", "Rehan", 0.0)))),
    ]:
        p = living("recv")
        assert transfer(q, p, 200).json()["transfer"] is not None             # 200 pending, below threshold
        gv._materiality_gate = late_receipt(p)
        try:
            out = runner(p)
        finally:
            gv._materiality_gate = real_gate
        assert out["cycle"] is not None, (label, out)
        assert out["cycle"]["inter_vsb_received_wst"] == 200.0, (label, out["cycle"].get("inter_vsb_received_wst"))
        assert tr.peek_pending_transfers(p) == 50000.0, label                  # the late receipt still waits

    # …and the venture-returns queue is capped the same way, on both paths
    from agentic_core.economy.ventures import peek_pending_returns, record_positions, record_return
    for label, runner in [("sync", lambda v: gv.governed_cycle_sync(v, "waqf_ltd_hybrid", "Rehan", 0.0)),
                          ("async", lambda v: asyncio.run(gv.governed_cycle(v, "waqf_ltd_hybrid", "Rehan", 0.0)))]:
        r_v2 = uid("returns")
        record_positions(r_v2, {"positions": [{"id": "h463", "name": "W463", "domain": "care",
                                               "score": 0.5, "amount_wst": 100000.0}]})
        record_return(r_v2, "h463", 300.0)

        def late_return(vsb_id, est, source, counterparty=None, intake=None, _v=r_v2):
            out = real_gate(vsb_id, est, source, counterparty, intake)
            if vsb_id == _v:
                record_return(_v, "h463", 40000.0, "w463 late return")        # lands between the gate and the cycle
            return out
        gv._materiality_gate = late_return
        try:
            ret = runner(r_v2)
        finally:
            gv._materiality_gate = real_gate
        assert ret["cycle"]["venture_returns_recycled_wst"] == 300.0 and peek_pending_returns(r_v2) == 40000.0, label


def test_w463_hold_lifecycle_reviews_races_and_replays_both_ways(client, monkeypatch):
    """W463 — the second refutation of the redesigned hold lifecycle, each finding pinned both ways. A hold is
    re-estimated only while SUBMITTED (never under review), and a decision is refused when the amount it would
    bind is not the amount the reviewer saw; a hold filed after a rejection says so and needs an explicit
    decision; every release is checked against the approved amount (a lower reserve rate, a vanished cost event,
    receipts that arrived after the approval); a heartbeat approval with no revenue events can be spent; a hold
    whose events were consumed elsewhere is retired; two live siblings are reconciled; a transfer that posted is
    never reported as failed because the gate raised afterwards, and its replay repairs the receiver leg even when
    the receiver has gone; the ledger answer does not wait on another writer's lock. The third refutation: a
    rejection stands only while no approved action has run since, and only for the same declared intake; a hold
    after a rejection says so from the moment it is filed (answer, queue row, notes, pages); a give-back never
    revives an approval beside a newer record; an event-less heartbeat approval whose receipts are gone is
    withdrawn, not spent; an economy hold cannot be "implemented" by hand; an allowed action that raised is
    retried and recorded as that, not as a gate outage. The fourth: a spend counts as "an approved action ran"
    only once its action started (marked where it starts), so an in-flight spend never lifts a rejection; one
    filing order that a backward clock step cannot disturb; an API approval whose receipts are gone is withdrawn;
    a give-back skips beside a newer rejected record and waits for the gate's lock; a record no action can
    release is retired, not stranded; an unreadable ledger is recorded as unknown. The fifth: an unmarked spend
    never refuses the rejected action for ever (it is asked, for an explicit decision); only a confirmed debit counts
    as a run; every start marker is guarded; a rejection says what rejected it; retiring is an admin decision, and a
    transfer approval whose receiver left the roster is retired with that reason. The sixth: a give-back
    withdraws undecided holds asked while its action was in flight (and otherwise writes that the action never
    ran); one reading decides and explains a retirement; a heartbeat hold for a VSB off the roster is unreleasable;
    an unreadable roster never retires; the roster's own writes no longer lose registrations or deregistrations
    made during a beat. The seventh: a give-back withdraws only holds its approval can release, and puts them back
    if the give-back does not land; an Owner decision landing mid-give-back survives; held beats and concurrent
    pruning keep the roster whole. The eighth: a newer approval already spent also keeps a give-back from
    reviving the older one, and every revert path is exercised. Virtual WST only.
    """
    import os
    import time as _time
    import threading
    import uuid as _uuid
    import pytest as _pytest
    from fastapi import HTTPException

    import agentic_core.gaas.v5 as g5
    from agentic_core.api import change_control as cca
    from agentic_core.config import atomic_write_json, store_lock
    from agentic_core.economy import governance as gv
    from agentic_core.economy import transfers as tr
    from agentic_core.economy.ledger import VirtualLedger
    from agentic_core.economy.living_vsbs import deregister, operate_vsb, register
    from agentic_core.economy.revenue import peek_pending, record_event

    monkeypatch.setattr(gv, "MATERIALITY_WST", 1000.0)

    def uid(tag):
        return f"w463l-{tag}-{_uuid.uuid4().hex[:6]}"

    def living(tag):
        v = uid(tag)
        register(v, f"W463L {tag}", "waqf_ltd_hybrid", "enterprise", "Rehan")
        return v

    def fund(v, revenue):
        monkeypatch.setattr(gv, "MATERIALITY_WST", 1e15)
        assert client.post("/api/v1/economy/cycle", json={"vsb_id": v, "revenue": revenue}).json()["cycle"]
        monkeypatch.setattr(gv, "MATERIALITY_WST", 1000.0)

    def rec(cid):
        return cca._load_change(cid)

    def decide(cid, verdict="approved", **extra):
        return client.post(f"/api/v1/cca/{cid}/review", json={"override_decision": verdict, "reviewer_notes": "w463l",
                                                            "admin_decision_for_critical": True, **extra})

    def cyc(v, revenue, costs=0.0, reserve_rate=0.2):
        return client.post("/api/v1/economy/cycle", json={"vsb_id": v, "revenue": revenue, "costs": costs,
                                                         "reserve_rate": reserve_rate}).json()

    # ── S1: the amount a decision binds is the amount the reviewer saw ──
    v1 = uid("review")
    h1 = cyc(v1, 5000)["governance"]
    seen = h1["est_distributable_wst"]
    assert cyc(v1, 6000)["governance"]["approved_or_filed_wst"] == 4800.0            # re-estimated (S5: response is current)
    stale = decide(h1["cca_id"], expected_est_distributable_wst=seen)
    assert stale.status_code == 409 and "changed since it was read" in stale.json()["detail"]
    assert rec(h1["cca_id"])["status"] == "submitted" and rec(h1["cca_id"])["est_distributable_wst"] == 4800.0
    # a hold under review is never re-estimated
    cca._update_change(h1["cca_id"], lambda f: f.update(status="under_review"))
    under = cyc(v1, 50000)["governance"]
    assert under["cca_id"] == h1["cca_id"] and "under review" in under["note"]
    assert rec(h1["cca_id"])["est_distributable_wst"] == 4800.0
    # …and a decision refuses if the amount moved DURING the review (defence in depth)
    real_query = cca.gateway.query

    async def _query_moves_amount(*a, **k):
        cca._update_change(h1["cca_id"], lambda f: f.update(est_distributable_wst=999999.0))
        return "[DECISION: APPROVED]"
    monkeypatch.setattr(cca.gateway, "query", _query_moves_amount)
    moved = client.post(f"/api/v1/cca/{h1['cca_id']}/review", json={"reviewer_notes": "w463l"})
    monkeypatch.setattr(cca.gateway, "query", real_query)
    assert moved.status_code == 409 and "changed during the review" in moved.json()["detail"]
    assert rec(h1["cca_id"])["status"] == "under_review"

    # ── S2: a hold filed after a rejection says so and needs an explicit decision ──
    v2 = uid("followrej")
    rej = cyc(v2, 50000)["governance"]["cca_id"]
    assert decide(rej, "rejected").status_code == 200
    nxt = cyc(v2, 50001)["governance"]
    after = rec(nxt["cca_id"])
    assert nxt["cca_id"] != rej and after["follows_rejection"]["cca_id"] == rej and "FOLLOWS A REJECTION" in after["description"]
    assert after["filed_ns"] > rec(rej)["filed_ns"]                                  # ordered within one second too

    async def _query_approves(*a, **k):
        return "[DECISION: APPROVED]"
    monkeypatch.setattr(cca.gateway, "query", _query_approves)
    reviewed = client.post(f"/api/v1/cca/{nxt['cca_id']}/review", json={"reviewer_notes": "w463l"})
    monkeypatch.setattr(cca.gateway, "query", real_query)
    # W464 — every economy hold is CRITICAL: a review holds it for the Owner (the follows link is information)
    assert reviewed.status_code == 200 and reviewed.json()["hold_reason"] == "critical_requires_admin_decision"
    assert reviewed.json()["recommendation"] == {"verdict": "approved", "source": "model_decision_marker"}
    assert rec(nxt["cca_id"])["status"] == "under_review"
    assert decide(nxt["cca_id"]).status_code == 200 and cyc(v2, 50001)["cycle"] is not None
    assert "follows_rejection" not in rec(cyc(v2, 60000)["governance"]["cca_id"])         # an action ran since: no link

    def tie_case(tag, rej_ns, imp_ns):
        # a rejection and a spent approval filed within one second: filed_ns orders them; an exact tie reads as the rejection
        v = uid(tag)
        common = {"title": gv._HOLD_TITLE_PREFIX + v, "change_type": "economy_material", "submitted_by": "economy:api",
                  "vsb_id": v, "impact_tier": "MEDIUM", "est_distributable_wst": 40000.0, "description": "",
                  "audit_trail": [], "submitted_at": "2026-09-13T00:00:09Z",
                  "intake": {"revenue_wst": 50000.0, "costs_wst": 0.0, "returns_wst": 0.0, "transfers_wst": 0.0,
                             "reserve_rate": 0.2}}
        for status, ns in (("rejected", rej_ns), ("implemented", imp_ns)):
            cid = f"cca-w463lt{_uuid.uuid4().hex[:6]}"
            atomic_write_json(cca._cca_path(cid), {**common, "cca_id": cid, "status": status,
                                                   **({"filed_ns": ns} if ns else {})})
            if status == "rejected":                  # listed after the spent record, so list order would pick it
                _old = _time.time() - 60
                os.utime(cca._cca_path(cid), (_old, _old))
        return "follows_rejection" in rec(cyc(v, 60000)["governance"]["cca_id"])
    assert tie_case("tie-spent-later", 1, 2) is False
    assert tie_case("tie-rejected-later", 2, 1) is True
    assert tie_case("tie-legacy", 0, 0) is True

